/* Week 3: three sequencing exercises, real MakeCode building and two-board radio. */
(function(){
'use strict';
const C=window.BeaconContent,L=window.BeaconLogic,$=q=>document.querySelector(q),app=$('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bi=(en,ko,tag='span',cls='')=>`<${tag}${cls?` class="${cls}"`:''}><span class="en">${esc(en)}</span><span class="ko" lang="ko">${esc(ko||en)}</span></${tag}>`;
const B=(p,tag='span',cls='')=>bi(p[0],p[1],tag,cls);
let s=null,key='',lang='en',saveOK=true,timer=null,previewTimer=null,toastTimer=null,mapPos=null,mapVisited=[],mapBusy=false,previewBusy=false,sequenceBusy=false,footerObserver=null;
const defaults=()=>({version:4,index:0,cardId:'read',visited:['read'],lang:'en',profile:{name:'',klass:'',device:'computer',board:'shared',teacher:false},fields:{},checks:{},answers:{},map:{seq:['F','F','F','S'],result:null,attempts:[]},mapLong:{seq:['F','','','','','','','S'],result:null,attempts:[]},signal:{order:['tick','pause-a','diamond','clear','pause-b'],result:null,attempts:[]},created:new Date().toISOString(),updated:''});
function valid(v){return !!(v&&v.version===4&&Number.isInteger(v.index)&&v.index>=0&&v.index<C.cards.length&&['en','ko'].includes(v.lang)&&v.fields&&v.checks&&v.answers&&v.map&&Array.isArray(v.map.seq)&&v.map.seq.length===4&&v.map.seq.every(x=>['F','R','S'].includes(x))&&Array.isArray(v.map.attempts)&&v.mapLong&&Array.isArray(v.mapLong.seq)&&v.mapLong.seq.length===8&&v.mapLong.seq.every(x=>['','F','R','S'].includes(x))&&Array.isArray(v.mapLong.attempts)&&v.signal&&Array.isArray(v.signal.order)&&v.signal.order.length===5&&new Set(v.signal.order).size===5&&v.signal.order.every(x=>L.signalTiles[x])&&Array.isArray(v.signal.attempts));}
function migrate(v){
 if(!v||![2,3].includes(v.version)||!Number.isInteger(v.index))return null;
 const legacyIds=v.version===2
  ?['read','recall','goals','map','editor','beacon','transfer','play','pit','extension','plenary']
  :['read','recall','goals','map','editor','beacon','transfer','play','radio1','radio2','pit','extension','plenary'];
 let id=legacyIds[v.index]||'read';
 if(id==='map')id={long:'map-long',signal:'signal'}[v.fields?.seqTab]||'map';
 if(id==='beacon')id=['beacon-one','beacon-two','beacon'][Math.max(0,Math.min(2,Number(v.fields?.buildStep)||0))];
 if(id==='radio1'&&v.checks?.radio1Tried)id='radio1-test';
 if(id==='radio2'&&v.checks?.radio2Tried)id='radio2-test';
 const d=defaults();const migrated={...d,...v,version:4,index:C.cards.findIndex(c=>c.id===id),cardId:id,visited:[id],mapLong:v.mapLong||d.mapLong,signal:v.signal||d.signal};
 return valid(migrated)?migrated:null;
}
function linearKey(name,klass){return L.storageKey(name,klass).replace('radio-v3-','linear-v4-');}
function brand(){return `<div class="brand"><span class="brandmark" aria-hidden="true">mi</span><div>MICROBIT INVENTORS<small>WITH MR DAVE · WEEK 03</small></div></div>`;}
function language(id,value){return `<select class="language" id="${id}" aria-label="Language / 언어"><option value="en"${value==='en'?' selected':''}>English</option><option value="ko"${value==='ko'?' selected':''}>English + 한국어</option></select>`;}
function option(value,label,current){return `<option value="${value}"${value===current?' selected':''}>${esc(label)}</option>`;}
function deviceOptions(value){return option('computer','Laptop / Chromebook · 노트북',value)+option('ipad','iPad / iPhone · 아이패드',value)+option('android','Android tablet · 안드로이드',value)+option('simulator','Simulator only · 시뮬레이터만',value);}
function led(name,mini=false){const cells=(L.icons[name]||L.icons.blank).join('');return `<span class="${mini?'block-display':'led-grid'}" role="img" aria-label="${esc(name)}">${[...cells].map(v=>mini?`<i class="${v==='1'?'on':''}"></i>`:`<i class="led${v==='1'?' on':''}"></i>`).join('')}</span>`;}
function signalStrip(){return `<div class="signal-strip" aria-label="Diamond, blank, diamond, blank, tick">${['diamond','blank','diamond','blank','tick'].map((n,i)=>`${i?'<b aria-hidden="true">→</b>':''}<span class="frame">${led(n)}</span>`).join('')}</div>`;}
function landing(){
 document.body.classList.toggle('bilingual',lang==='ko');
 let last=null;try{last=JSON.parse(localStorage.getItem('beetlebit-w3-linear-last')||localStorage.getItem('beetlebit-w3-radio-last')||'null');}catch{}
 app.innerHTML=`<main class="landing" id="main"><header class="landing-head">${brand()}${language('landing-lang',lang)}</header><div class="landing-grid"><section><p class="eyebrow">WEEK 03 · MAKECODE + MICRO:BIT</p><h1 class="landing-title">Make a<br><em>rescue beacon.</em><span class="ko" lang="ko">구조 신호등 만들기</span></h1>${bi('Build a signal. Then send a command by radio.','신호를 만든 뒤 무선으로 명령을 보내요.','p','lead')}${signalStrip()}<div class="landing-steps"><span>01 · ${bi('Three sequence challenges','순서 도전 세 가지')}</span><span>02 · ${bi('Build in MakeCode','MakeCode로 만들기')}</span><span>03 · ${bi('Two-board radio','기기 두 개로 무선 통신')}</span></div>${bi('Most of this session is for making and testing your own program. Use English, Korean or both.','수업의 대부분은 직접 프로그램을 만들고 확인하는 시간이에요. 영어, 한국어 또는 두 언어를 사용해요.','p','muted')}</section><section class="entry-card"><p class="eyebrow">90 MINUTES · NO ROBOT KIT NEEDED</p>${bi('Ready to make something?','만들 준비가 됐나요?','h2')}<form id="entry-form"><label class="field" for="name">${bi('First name','이름')}<input id="name" name="name" maxlength="40" autocomplete="off" required></label><label class="field" for="klass">${bi('Class','반')}<input id="klass" name="klass" maxlength="30" autocomplete="off" placeholder="6A"></label><label class="field" for="device">${bi('My device','사용하는 기기')}<select id="device">${deviceOptions('computer')}</select></label><label class="field" for="board">${bi('My micro:bit today','오늘 사용할 micro:bit')}<select id="board"><option value="pair">Two boards for our team · 우리 팀에 기기 두 개</option><option value="shared" selected>Shared with a partner · 친구와 함께</option><option value="own">One for me · 혼자 사용</option><option value="none">No board today · 오늘은 기기 없음</option></select></label><p id="entry-error" class="feedback retry" hidden role="alert"></p><button type="submit" class="primary full">${bi('Start making →','만들기 시작 →')}</button></form>${last&&last.name?`<button class="ghost full" data-action="resume">${bi('Resume '+last.name+' · '+last.klass,last.name+' · '+last.klass+' 이어서 하기')}</button>`:''}${bi('Work is saved in this browser, not sent to a teacher. Use the same name and class to resume.','활동은 이 브라우저에 저장되며 선생님께 자동으로 전송되지 않아요. 같은 이름과 반으로 이어서 할 수 있어요.','p','caption')}</section></div><footer class="landing-footer">${bi('Bring your device and data cable. Radio challenges use two powered micro:bits per team. With no board pair, build both projects and peer-trace instead.','기기와 데이터 케이블을 준비해요. 무선 도전에는 팀마다 전원을 켠 micro:bit 두 개가 필요해요. 기기가 없으면 프로젝트를 만들고 친구와 전달 과정을 따라가요.','p','caption')}</footer></main>`;
}
function start(p,resume=false){
 const teacher=p.name.trim().toLowerCase()==='teacher';p={name:p.name.trim().slice(0,40),klass:p.klass.trim().slice(0,30),device:p.device,board:p.board,teacher};
 s=defaults();key=linearKey(p.name,p.klass);saveOK=true;
 try{
  let v=JSON.parse(localStorage.getItem(key)||'null');
  if(!valid(v)&&!teacher)v=migrate(JSON.parse(localStorage.getItem(L.storageKey(p.name,p.klass))||'null'))||migrate(JSON.parse(localStorage.getItem(L.storageKey(p.name,p.klass,true))||'null'));
  if(valid(v)&&!teacher){s={...defaults(),...v};const i=C.cards.findIndex(c=>c.id===s.cardId);if(i>=0)s.index=i;}
 }catch{saveOK=false;}
 s.profile=p;if(!resume)s.lang=lang;lang=s.lang;
 if(!Array.isArray(s.visited))s.visited=[];
 s.cardId=C.cards[s.index].id;if(!s.visited.includes(s.cardId))s.visited.push(s.cardId);
 if(!teacher)try{localStorage.setItem('beetlebit-w3-linear-last',JSON.stringify(p));}catch{saveOK=false;}
 render(true);save();
}
function save(){if(!s||s.profile.teacher)return;s.updated=new Date().toISOString();try{localStorage.setItem(key,JSON.stringify(s));}catch{saveOK=false;}const w=$('#save-warning');if(w)w.hidden=saveOK;}
function setField(k,v){s.fields[k]=v;save();updateProgress();}
function answered(k){return s.answers[k]===C.questions[k].answer;}
function explained(k){return !!String(s.fields[k]||'').trim()||!!s.checks[k+'Oral'];}
function done(id){const c=s.checks,f=s.fields;return !!({
 read:c.ready,recall:answered('recall'),goals:c.goals,
 map:s.map.result?.success,'map-long':s.mapLong.result?.success,signal:s.signal.result?.success,
 editor:c.editorA,'beacon-one':c.oneFlash,'beacon-two':c.twoFlashBuilt,beacon:c.beaconTest&&answered('gap'),
 transfer:!!f.physical&&c.simulatorTest,play:!!f.changeChoice&&!!f.changeWhere&&explained('change')&&c.changeRetest,
 radio1:c.radio1SenderBuilt,'radio1-receiver':c.radio1ReceiverBuilt,'radio1-test':!!f.radio1Where&&c.radio1Tried&&answered('radioStart'),
 radio2:c.radio2SenderBuilt,'radio2-receiver':c.radio2ReceiverBuilt,'radio2-test':!!f.radio2Where&&c.radio2Tried&&explained('radioExplain'),'radio2-debug':answered('radioSpelling'),
 pit:!!f.phase&&c.pitShow,extension:!!f.extension&&c.extensionTried,plenary:answered('exit')&&explained('final')&&c.projectSaved
 }[id]);}
function completedCount(){return C.cards.filter(c=>done(c.id)).length;}
function check(k,en,ko){return `<label class="check"><input type="checkbox" data-check="${k}"${s.checks[k]?' checked':''}>${bi(en,ko)}</label>`;}
function text(k,en,ko,placeholder=''){return `<label class="field">${bi(en,ko)}<textarea data-field="${k}" maxlength="700" placeholder="${esc(placeholder)}">${esc(s.fields[k]||'')}</textarea></label>`;}
function oral(k){return check(k+'Oral','I explained it aloud or pointed and demonstrated.','말로 설명하거나 가리키며 직접 보여 줬어요.');}
function radio(k,choices){return `<div class="chip-options">${choices.map(([v,p])=>`<button type="button" data-choice="${k}" data-value="${v}" class="${s.fields[k]===v?'chosen':''}" aria-pressed="${s.fields[k]===v}">${B(p)}</button>`).join('')}</div>`;}
function details(title,content,open=false){return `<details${open?' open':''}><summary>${B(title)}</summary><div class="details-content">${content}</div></details>`;}
function steps(items){return `<div class="step-list">${items.map((p,i)=>`<div class="step-item"><span class="step-number">${i+1}</span><div>${B(p,'p')}</div></div>`).join('')}</div>`;}
function mcLink(){return `<a href="https://makecode.microbit.org/" target="_blank" rel="noopener noreferrer" class="primary" data-action="open-editor">${bi('Open MakeCode ↗','MakeCode 열기 ↗')}</a>`;}
function where(){return `<div class="where row spread"><div><strong>${bi('Work in MakeCode now.','지금은 MakeCode에서 활동해요.')}</strong>${bi('Keep this guide open. Build and test in the other tab or app.','이 안내를 열어 두고 다른 탭이나 앱에서 만들고 확인해요.','div','small')}</div>${mcLink()}</div>`;}
function quiz(id){const q=C.questions[id],a=s.answers[id];return `<section class="quiz" aria-label="Quick check"><h3>${B(q.q)}</h3>${q.options.map(([v,p],i)=>`<button class="choice${a===v?' chosen':''}" data-answer="${id}" data-value="${v}" aria-pressed="${a===v}"><span class="choice-letter">${String.fromCharCode(65+i)}</span>${B(p)}</button>`).join('')}${a?`<div class="feedback ${a===q.answer?'good':'retry'}" role="status">${B(a===q.answer?q.good:q.hint)}</div>`:''}${details(['Need a clue?','힌트가 필요한가요?'],B(q.hint,'p'))}</section>`;}
function blockIcon(name='diamond'){return `<div class="block">show icon ${led(name,true)}</div>`;}
function blockPause(n=500){return `<div class="block">pause (ms) <span class="block-num">${n}</span></div>`;}
function blockClear(){return '<div class="block">clear screen</div>';}
function flashBlocks(){return blockIcon()+blockPause()+blockClear()+blockPause();}
function eventBlock(body,label='on button A pressed'){return `<div class="block-event"><div class="event-label">${esc(label)}</div><div class="block-body">${body}</div></div>`;}
function blockGuide(kind){let body=blockIcon(),label=['Block guide · copy into MakeCode','블록 안내 · MakeCode에서 만들어요'];if(kind==='one')body=flashBlocks();if(kind==='full')body=flashBlocks()+flashBlocks()+blockIcon('tick');if(kind==='repeat')body=`<div class="block loop">repeat <span class="block-num">2</span> times<div style="height:9px"></div>${flashBlocks()}</div>`+blockIcon('tick');if(kind==='shake')body=blockIcon('heart');return `<div class="block-guide">${B(label,'p','caption')}${eventBlock(body,kind==='shake'?'on shake':'on button A pressed')}${bi('English block labels stay the same. Korean explanations sit beside them.','영어 블록 이름은 그대로 두고 한국어로 설명해요.','p','caption')}</div>`;}
function preview(){return `<div class="panel navy"><p class="eyebrow">FINISHED SIGNAL · EXAMPLE ONLY</p><div class="microbit-preview"><div class="microbit-face"><button class="board-button" data-action="preview" aria-label="Play example with A">A</button><div id="preview-leds">${led('tick')}</div><span class="board-button" aria-hidden="true" style="display:grid;place-items:center">B</span></div><p id="preview-status" class="preview-caption">${bi('Tap A to watch the example.','A를 눌러 예시를 봐요.')}</p><div class="pin-strip"><span>0</span><span>1</span><span>2</span><span>3V</span><span>GND</span></div></div>${bi('This is a demonstration, not your code. You will make your own in MakeCode.','이것은 예시이며 여러분의 코드가 아니에요. MakeCode에서 직접 만들 거예요.','p','caption')}</div>`;}
function nav(){
 if(s.profile.teacher)return `<nav class="stage-nav" aria-label="Teacher step navigation">${C.cards.map((c,i)=>`<button class="nav-btn${i===s.index?' active':''}${done(c.id)?' done':''}" data-go="${i}"${i===s.index?' aria-current="step"':''}><span class="nav-num">${i+1}</span>${B(c.title)}</button>`).join('')}</nav>`;
 const groups=[['start',['Get ready','준비하기']],['sequence',['Main task 1 · Sequences','주요 활동 1 · 순서']],['build',['Main task 2 · Build','주요 활동 2 · 만들기']],['radio',['Main task 2 · Radio','주요 활동 2 · 무선']],['reflect',['Reflect and finish','돌아보고 마무리']]];
 return `<section class="journey-rail" aria-label="Lesson overview"><p class="caption">${bi('Your learning journey','배움의 순서')}</p><ol>${groups.map(([id,p],i)=>`<li class="${C.cards[s.index].section===id?'current':''}"${C.cards[s.index].section===id?' aria-current="step"':''}><span class="journey-dot">${i+1}</span>${B(p)}</li>`).join('')}</ol><p class="caption">${bi('Use Next at the bottom. Each challenge will appear in order.','아래의 다음 버튼을 눌러요. 도전이 차례대로 나와요.')}</p></section>`;
}
function rail(){return `<aside class="sidebar"><details ${innerWidth>850?'open':''}><summary>${bi('Our learning focus','오늘의 배움')}</summary><div class="details-content"><dl><dt>WAGBA</dt><dd>${B(C.wagba)}</dd></dl>${Object.entries(C.goals).map(([k,p])=>`<dl><dt>${{K:'KNOWLEDGE',S:'SKILLS',U:'UNDERSTANDING'}[k]} · ${k}</dt><dd>${B(p)}</dd></dl>`).join('')}<button class="secondary full" data-action="words">${bi('Word & language help','단어와 설명 도움말')}</button></div></details>${nav()}</aside>`;}
function shell(){
 const c=C.cards[s.index],last=s.index===C.cards.length-1,start=C.cards.slice(0,s.index).reduce((a,x)=>a+x.mins,0);
 document.body.classList.toggle('bilingual',s.lang==='ko');
 app.innerHTML=`<header class="topbar">${brand()}<div class="top-actions">${s.profile.teacher?'<span class="teacher-badge">TEACHER REVIEW</span>':`<span class="identity">${esc(s.profile.name)} · ${esc(s.profile.klass)}</span>`}${language('lesson-lang',s.lang)}<button class="ghost" data-action="tools">${bi('Tools','도구')}</button><button class="ghost" data-action="record">${bi('My record','내 기록')}</button></div></header>
 <div class="app-grid">${rail()}<main class="lesson" id="main" tabindex="-1">
 <div class="journey-heading"><strong>${bi(`Step ${s.index+1} of ${C.cards.length}`,`${C.cards.length}단계 중 ${s.index+1}단계`)}</strong><span class="caption">${bi('One step at a time. Use Next below.','한 단계씩 해요. 아래의 다음 버튼을 눌러요.')}</span></div>
 <div class="lesson-progress" role="progressbar" aria-label="Lesson position" aria-valuemin="1" aria-valuemax="${C.cards.length}" aria-valuenow="${s.index+1}"><span style="width:${Math.round((s.index+1)/C.cards.length*100)}%"></span></div>
 ${s.profile.teacher?`<label class="field teacher-jump">Teacher jump to step<select id="jump">${C.cards.map((card,i)=>option(String(i),`${i+1}. ${card.title[0]}`,String(s.index))).join('')}</select></label>`:''}
 <div id="save-warning" class="save-warning"${saveOK?' hidden':''}>${bi('This browser could not save progress. Export your record before leaving.','이 브라우저에 활동을 저장하지 못했어요. 나가기 전에 기록을 내려받아요.')}</div>
 <article class="activity" data-card-id="${c.id}"><div class="card-meta"><span>${B(c.stage)}</span>${s.profile.teacher?`<span class="timer-note">${start}–${start+c.mins} min</span>`:''}</div>
 <h2 id="activity-title">${B(c.title)}</h2>${B(c.intro,'p','card-intro')}<div id="card-body">${cardBody(c.id)}</div>
 <div class="step-end">${bi(last?'Finished? Keep your record using the button below.':'Finished this step? Use the Next button below.',last?'마쳤나요? 아래 버튼으로 기록을 남겨요.':'이 단계를 마쳤나요? 아래의 다음 버튼을 눌러요.')}</div>
 ${s.profile.teacher?`<details class="teacher-box"><summary>Teacher notes · ${esc(c.mins)} minutes</summary><div class="details-content"><p>${esc(c.teacher)}</p></div></details>`:''}</article></main></div>
 <footer class="footerbar" aria-label="Step navigation"><div class="footer-status" id="footer-status"></div><div class="actions"><button class="secondary" data-action="prev"${s.index===0?' disabled':''}>${bi('← Back','← 이전')}</button><button class="primary" data-action="${last?'record':'next'}">${last?bi('Finish & keep record','마치고 기록 남기기'):bi('Next →','다음 →')}</button></div></footer>`;
 updateProgress();syncFooter();
}
function syncFooter(){
 if(footerObserver)footerObserver.disconnect();
 const footer=$('.footerbar');if(!footer)return;
 const measure=()=>document.documentElement.style.setProperty('--footer-height',Math.ceil(footer.getBoundingClientRect().height)+'px');
 measure();if('ResizeObserver' in window){footerObserver=new ResizeObserver(measure);footerObserver.observe(footer);}
}
function updateProgress(){
 if(!s)return;const c=C.cards[s.index],next=C.cards[s.index+1],f=$('#footer-status');
 if(f)f.innerHTML=`<div class="footer-position">${bi(`Step ${s.index+1} / ${C.cards.length}`,`${s.index+1} / ${C.cards.length}단계`)}<span class="save-indicator">${bi(s.profile.teacher?'Teacher preview':saveOK?'Saved here':'Not saved',s.profile.teacher?'교사용 미리 보기':saveOK?'이 기기에 저장됨':'저장되지 않음')}</span></div><div class="next-preview">${next?bi('Next: '+next.title[0],'다음: '+next.title[1]):bi('Keep a copy of your work.','활동 기록을 보관해요.')}</div>`;
 document.querySelectorAll('.nav-btn').forEach(el=>{const i=Number(el.dataset.go);el.classList.toggle('done',done(C.cards[i].id));});
}
function cancelTimers(){clearTimeout(timer);clearTimeout(previewTimer);timer=null;previewTimer=null;mapBusy=false;previewBusy=false;sequenceBusy=false;}
function render(scroll=false){cancelTimers();mapPos=null;mapVisited=[];shell();if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}}
function go(index){
 if(!Number.isInteger(index))return;
 s.index=Math.max(0,Math.min(C.cards.length-1,index));s.cardId=C.cards[s.index].id;
 if(!s.visited.includes(s.cardId))s.visited.push(s.cardId);
 save();render(true);
}
function cardBody(id){
 switch(id){
 case 'read':return `<div class="two-col"><div class="stack">${steps([['Press A: show two flashes, then a tick.','A 버튼을 누르면 두 번 깜박이고 체크 표시가 나타나요.'],['Build it in MakeCode, then test the real board.','MakeCode에서 만들고 실제 기기에서 확인해요.'],['Send HELP from another micro:bit to start your signal.','다른 micro:bit에서 HELP를 보내 신호를 시작해요.']])}<div class="note">${bi('Three short sequence challenges first. Then build a beacon and control it from another micro:bit.','먼저 짧은 순서 도전 세 가지를 해요. 그다음 신호등을 만들고 다른 micro:bit로 조종해요.','p')}</div><h3>${bi('Choose your first role','처음 할 역할을 골라요')}</h3>${radio('role',[['driver',['Driver: change the code','조종자: 코드 바꾸기']],['navigator',['Navigator: predict and check','길잡이: 예상하고 확인하기']],['solo',['Working on my own','혼자 활동하기']]])}${check('ready','I know what I will make today.','오늘 무엇을 만들지 알아요.')}</div>${preview()}</div>`;
 case 'recall':return `<div class="two-col">${blockGuide('starter')}<div>${quiz('recall')}${bi('Point to the event and the output. You can explain in either language.','이벤트와 결과를 가리켜요. 편한 언어로 설명해도 좋아요.','p','caption')}</div></div>`;
 case 'goals':return `<div class="three-col">${Object.entries(C.goals).map(([k,p])=>`<section class="panel"><p class="eyebrow">${{K:'KNOWLEDGE',S:'SKILLS',U:'UNDERSTANDING'}[k]} · ${k}</p>${B(p,'p')}</section>`).join('')}</div><div class="note">${bi('Sequence = order. Pause = wait. Debug = find, fix, test.','Sequence는 순서, pause는 기다리기, debug는 잘못된 부분을 찾아 고치고 확인하기예요.','p')}</div>${check('goals','I will build in MakeCode and explain one change.','MakeCode에서 만들고 바꾼 부분 하나를 설명할 거예요.')}${details(['School Types of Learning picture','학교의 배움 종류 그림'],`<img src="assets/types-of-learning.jpg" alt="School Types of Learning reference. The lesson goals are written above in English and Korean." loading="lazy">`)}`;
 case 'map':return mapCard();
 case 'map-long':return longMapCard();
 case 'signal':return signalCard();
 case 'editor':return editorCard();
 case 'beacon-one':return beaconCard(0);
 case 'beacon-two':return beaconCard(1);
 case 'beacon':return beaconCard(2);
 case 'transfer':return transferCard();
 case 'play':return playCard();
 case 'radio1':return radio1Card('sender');
 case 'radio1-receiver':return radio1Card('receiver');
 case 'radio1-test':return radio1Card('test');
 case 'radio2':return radio2Card('sender');
 case 'radio2-receiver':return radio2Card('receiver');
 case 'radio2-test':return radio2Card('test');
 case 'radio2-debug':return radio2Card('debug');
 case 'pit':return pitCard();
 case 'extension':return extensionCard();
 case 'plenary':return plenaryCard();
 default:return '';
 }
}
function grid(pos={x:0,y:2,d:0},visited=[]){return `<div class="grid-map" role="img" aria-label="Three by three route grid. Robot starts bottom left facing up. Rescue target in the centre.">${Array.from({length:9},(_,i)=>{const x=i%3,y=Math.floor(i/3),target=x===1&&y===1,isRobot=pos.x===x&&pos.y===y;return `<div class="map-cell${target?' target':''}${visited.some(p=>p.x===x&&p.y===y)?' visited':''}">${isRobot?`<span class="robot-token" aria-label="Robot facing ${['up','right','down','left'][pos.d]}">${['↑','→','↓','←'][pos.d]}</span>`:target?'⚑':''}${target?'<span class="target-mark">RESCUE</span>':''}</div>`;}).join('')}</div>`;}
function mapCard(){return `<div class="two-col"><div class="panel"><div id="map-grid">${grid()}</div><div class="legend"><span>↑ ${bi('Robot facing up','위쪽을 보는 로봇')}</span><span>⚑ ${bi('Rescue point','구조 지점')}</span></div>${bi('FORWARD follows the robot’s nose. TURN RIGHT changes direction in the same square.','앞으로 가기는 로봇이 바라보는 방향으로 가요. 오른쪽으로 돌 때는 같은 칸에 있어요.','p','small')}</div><div><h3>${bi('Change instruction 2.','2번째 명령을 바꿔요.')}</h3>${bi('Use: forward → turn right → forward → stop.','앞으로 → 오른쪽으로 돌기 → 앞으로 → 멈추기 순서로 해요.','p')}<div class="command-row">${s.map.seq.map((c,i)=>`<label class="command-slot">${i+1}<select data-command="${i}" aria-label="Instruction ${i+1}">${option('F','↑ F',c)}${option('R','↻ R',c)}${option('S','■ S',c)}</select></label>`).join('')}</div><div class="legend"><span>F · ${bi('Forward','앞으로')}</span><span>R · ${bi('Turn right','오른쪽 돌기')}</span><span>S · ${bi('Stop','멈추기')}</span></div><div class="actions"><button class="primary" data-action="run-map">${bi('Test the route','경로 확인하기')}</button><button class="secondary" data-action="reset-map">${bi('Reset position','위치 되돌리기')}</button></div><div id="map-result">${s.map.result?mapFeedback(s.map.result):bi('Predict first. Where will the robot stop?','먼저 예상해요. 로봇은 어디에서 멈출까요?','p','caption')}</div>${details(['Show me the first step','첫 단계 보여 주기'],bi('The first F moves up one square. Next, the robot must turn right—not move forward again. Change tile 2 from F to R.','첫 F는 위로 한 칸 가요. 다음에는 앞으로 또 가는 것이 아니라 오른쪽으로 돌아야 해요. 2번째 타일을 F에서 R로 바꿔요.','p'))}</div></div><div class="note">${bi('Ready for more? Select 2 · Two turns or 3 · Order the signal above.','더 해 볼까요? 위에서 2 · 두 번 돌기 또는 3 · 신호 순서 만들기를 골라요.','p')}</div>${bi('This is a planning model. It does not control or test real motors.','이것은 계획 모형이며 실제 모터를 조종하거나 확인하는 것이 아니에요.','p','caption')}`;}
function mapFeedback(r){return `<div class="feedback ${r.success?'good':'retry'}" role="status">${r.success?bi('✓ Turn repaired. Try challenge 2 or 3, or start your MakeCode build.','✓ 회전 명령을 고쳤어요. 2번이나 3번에 도전하거나 MakeCode로 이동해요.'):r.status==='outside'?bi(`Instruction ${r.at} tries to leave the grid. Check the second instruction.`,`${r.at}번째 명령에서 격자 밖으로 나가려고 해요. 2번째 명령을 확인해요.`):bi('The robot has not stopped at the rescue point. Check the order, then test again.','로봇이 구조 지점에서 멈추지 않았어요. 순서를 확인한 뒤 다시 실행해요.')}</div>`;}
function runMap(){if(mapBusy)return;cancelTimers();mapBusy=true;const seq=[...s.map.seq],r=L.route(seq);let i=0;s.map.result=null;mapVisited=[];document.querySelectorAll('[data-command]').forEach(x=>x.disabled=true);const btn=$('[data-action="run-map"]');if(btn)btn.disabled=true;
 const advance=()=>{if(!mapBusy||C.cards[s.index].id!=='map')return;mapPos=r.trace[i];mapVisited.push(mapPos);$('#map-grid').innerHTML=grid(mapPos,mapVisited);$('#map-result').innerHTML=bi(i===0?'Start position':`Instruction ${i} of 4`,i===0?'시작 위치':`4개 중 ${i}번째 명령`,'p','caption');i++;if(i<r.trace.length){timer=setTimeout(advance,650);}else{mapBusy=false;s.map.result={...r,seq,time:new Date().toISOString()};s.map.attempts.push({seq,success:r.success,status:r.status,time:new Date().toISOString()});s.map.attempts=s.map.attempts.slice(-8);$('#map-result').innerHTML=mapFeedback(r);document.querySelectorAll('[data-command]').forEach(x=>x.disabled=false);if(btn)btn.disabled=false;save();updateProgress();}};advance();}


function mapGrid(level,pos,visited=[]){
 const m=L.maps[level];pos=pos||m.start;
 return `<div class="grid-map${level?' grid-four':''}" role="img" aria-label="${level?'Four by four route. Start bottom left facing up. Target third column, third row. Two blocked squares in column two, rows three and four.':'Three by three route. Start bottom left facing up. Target in the centre.'}">${Array.from({length:m.size*m.size},(_,i)=>{
 const x=i%m.size,y=Math.floor(i/m.size),target=x===m.target.x&&y===m.target.y,robot=pos.x===x&&pos.y===y,blocked=m.obstacles.some(p=>p.x===x&&p.y===y);
 return `<div class="map-cell${target?' target':''}${blocked?' obstacle':''}${visited.some(p=>p.x===x&&p.y===y)?' visited':''}">${robot?`<span class="robot-token" aria-label="Robot facing ${['up','right','down','left'][pos.d]}">${['↑','→','↓','←'][pos.d]}</span>`:blocked?'×':target?'⚑':''}${target?'<span class="target-mark">GOAL</span>':''}</div>`;
 }).join('')}</div>`;
}
function longMapCard(){
 return `<div class="two-col"><div class="panel"><h3>${bi('Go around the blocked squares.','막힌 칸을 돌아서 가요.')}</h3><div id="long-grid">${mapGrid(1)}</div><div class="legend"><span>↑ ${bi('Robot','로봇')}</span><span>× ${bi('Blocked','막힌 칸')}</span><span>⚑ ${bi('Goal','목표')}</span></div>${bi('Turn on the spot. Forward follows the way the robot faces—even after a second turn.','같은 칸에서 돌아요. 두 번 돈 뒤에도 로봇이 바라보는 쪽으로 앞으로 가요.','p','small')}</div><div><h3>${bi('Build an eight-instruction route.','명령 여덟 개로 경로를 만들어요.')}</h3>${bi('Use five FORWARD, two TURN RIGHT and one STOP. Keep STOP last.','앞으로 다섯 번, 오른쪽 돌기 두 번, 멈추기 한 번을 사용해요. 멈추기는 맨 끝에 놓아요.','p')}<div class="command-row long-commands">${s.mapLong.seq.map((v,i)=>`<label class="command-slot">${i+1}<select data-long-command="${i}" aria-label="Long route instruction ${i+1}">${option('','?',v)}${option('F','↑ F',v)}${option('R','↻ R',v)}${option('S','■ S',v)}</select></label>`).join('')}</div><div class="legend"><span>F · ${bi('Forward','앞으로')}</span><span>R · ${bi('Turn right','오른쪽 돌기')}</span><span>S · ${bi('Stop','멈추기')}</span></div><div class="actions"><button class="primary" data-action="run-long">${bi('Test my sequence','내 순서 확인하기')}</button><button class="secondary" data-action="reset-map">${bi('Reset position','위치 되돌리기')}</button></div><div id="long-result" aria-live="polite">${s.mapLong.result?longFeedback(s.mapLong.result):bi('Predict: after the second turn, which way will the robot face?','예상해 봐요. 두 번째로 돈 뒤 로봇은 어느 쪽을 볼까요?','p','caption')}</div>${details(['Show me the first step','첫 단계 보여 주기'],bi('Start with two FORWARD instructions. You are now above the blocked squares. Then turn right.','먼저 앞으로 두 번 가요. 이제 막힌 칸보다 위에 있어요. 그다음 오른쪽으로 돌아요.','p'))}</div></div>`;
}
function longFeedback(r){
 const msg=r.success?['✓ Two turns worked. Show your partner the direction after each turn.','✓ 두 번 돌아 성공했어요. 돌 때마다 로봇이 보는 방향을 친구에게 보여 줘요.']:
 r.status==='invalid'?['Choose a command for every numbered space before testing.','확인하기 전에 모든 번호에 명령을 골라요.']:
 r.status==='blocked'?[`Instruction ${r.at} enters a blocked square. Find a route above it.`,`${r.at}번째 명령이 막힌 칸으로 들어가요. 그 위로 가는 길을 찾아요.`]:
 r.status==='outside'?[`Instruction ${r.at} leaves the grid. Check the robot’s direction.`,`${r.at}번째 명령이 격자 밖으로 나가요. 로봇이 보는 방향을 확인해요.`]:
 r.status==='early'?['STOP ended the program before all instructions ran. Put STOP last.','명령을 모두 실행하기 전에 멈췄어요. STOP을 맨 끝에 놓아요.']:
 ['Not at the goal yet. Trace one instruction at a time and try again.','아직 목표에 도착하지 않았어요. 명령을 하나씩 따라가며 다시 해 봐요.'];
 return `<div class="feedback ${r.success?'good':'retry'}" role="status">${B(msg)}</div>`;
}
function runLong(){
 if(mapBusy)return;cancelTimers();mapBusy=true;const seq=[...s.mapLong.seq],r=L.route(seq,1);let i=0;const visited=[];s.mapLong.result=null;
 document.querySelectorAll('[data-long-command]').forEach(el=>el.disabled=true);const btn=$('[data-action="run-long"]');if(btn)btn.disabled=true;
 function advance(){
  if(!mapBusy||C.cards[s.index].id!=='map-long')return;
  const pos=r.trace[i];visited.push(pos);$('#long-grid').innerHTML=mapGrid(1,pos,visited);$('#long-result').innerHTML=bi(i===0?'Start position':`Instruction ${i} of 8`,i===0?'시작 위치':`8개 중 ${i}번째 명령`,'p','caption');i++;
  if(i<r.trace.length){timer=setTimeout(advance,600);}else{mapBusy=false;s.mapLong.result={...r,seq,time:new Date().toISOString()};s.mapLong.attempts.push({seq,success:r.success,status:r.status,time:new Date().toISOString()});s.mapLong.attempts=s.mapLong.attempts.slice(-8);$('#long-result').innerHTML=longFeedback(r);document.querySelectorAll('[data-long-command]').forEach(el=>el.disabled=false);if(btn)btn.disabled=false;save();updateProgress();}
 }advance();
}

function signalCard(){
 return `<div class="two-col"><div class="stack"><h3>${bi('One flash, then a tick.','한 번 깜박인 뒤 체크 표시.')}</h3>${bi('Inside Button A, show a diamond, wait, clear the LEDs, wait again, then show a tick. Use ↑ and ↓ to put these five blocks in order.','A 버튼 안에서 마름모를 보여 주고, 기다리고, LED를 지우고, 다시 기다린 뒤 체크 표시를 보여 줘요. ↑와 ↓로 다섯 블록의 순서를 바꿔요.','p')}<div class="signal-order" aria-label="Reorder these five instructions">${s.signal.order.map((v,i)=>{const t=L.signalTiles[v];return `<div class="order-row"><span class="order-number">${i+1}</span><div class="order-block">${t.icon?led(t.icon,true):'<span class="time-icon" aria-hidden="true">◷</span>'}${bi(t.en,t.ko)}</div><div class="order-controls"><button class="secondary" data-move-signal="${i}" data-direction="-1"${i===0?' disabled':''} aria-label="Move instruction ${i+1} up / 위로">↑</button><button class="secondary" data-move-signal="${i}" data-direction="1"${i===4?' disabled':''} aria-label="Move instruction ${i+1} down / 아래로">↓</button></div></div>`;}).join('')}</div><div class="actions"><button class="primary" data-action="run-signal">${bi('Run my sequence','내 순서 실행하기')}</button></div></div><div class="stack"><div class="panel navy"><p class="eyebrow">SEQUENCE MODEL · NOT MAKECODE</p><div class="signal-stage" id="signal-leds">${led('tick')}</div><p id="signal-status" aria-live="polite">${bi('Your ordered instructions will run here.','여러분이 정한 순서가 여기에 실행돼요.')}</p></div><div id="signal-result" aria-live="polite">${s.signal.result?signalFeedback(s.signal.result):''}</div>${details(['Need a clue?','힌트가 필요한가요?'],bi('The diamond must appear first. Put a pause after clear screen so the dark gap is visible. The tick is last.','마름모가 먼저 나와야 해요. clear screen 뒤에 pause를 놓으면 불이 꺼진 시간을 볼 수 있어요. 체크 표시는 맨 끝이에요.','p'))}<p class="caption">${bi('This browser model practises order. You will build and test your real program in MakeCode next. Both pause blocks are identical and may swap places.','이 브라우저 모형에서는 순서를 연습해요. 다음에는 MakeCode에서 실제 프로그램을 만들고 확인해요. 두 pause 블록은 같아서 서로 바꿔 놓아도 돼요.')}</p></div></div>`;
}
function signalFeedback(r){return `<div class="feedback ${r.success?'good':'retry'}" role="status">${r.success?bi('✓ Your sequence has a visible flash, a dark gap and a finishing tick.','✓ 신호가 깜박이고, 잠시 꺼지고, 마지막에 체크 표시가 나와요.'):bi(`Look again at instruction ${r.at||1}. Does it match the signal you were asked to make?`,`${r.at||1}번째 명령을 다시 봐요. 만들기로 한 신호의 순서와 맞나요?`)}</div>`;}
function moveSignal(i,d){
 const j=i+d;if(i<0||j<0||i>4||j>4)return;cancelTimers();[s.signal.order[i],s.signal.order[j]]=[s.signal.order[j],s.signal.order[i]];s.signal.result=null;save();render();$(`[data-move-signal="${j}"][data-direction="${d}"]`)?.focus({preventScroll:true});
}
function runSignal(){
 if(sequenceBusy)return;cancelTimers();sequenceBusy=true;const order=[...s.signal.order],r=L.signalCheck(order);let i=0;s.signal.result=null;
 document.querySelectorAll('[data-move-signal],[data-action="run-signal"]').forEach(el=>el.disabled=true);
 function advance(){
  if(!sequenceBusy||C.cards[s.index].id!=='signal')return;
  if(i===order.length){sequenceBusy=false;s.signal.result={...r,order,time:new Date().toISOString()};s.signal.attempts.push({order,success:r.success,time:new Date().toISOString()});s.signal.attempts=s.signal.attempts.slice(-8);$('#signal-result').innerHTML=signalFeedback(r);$('#signal-status').innerHTML=bi('Model finished. Change the order or move on.','모형 실행이 끝났어요. 순서를 바꾸거나 다음 활동으로 가요.');document.querySelectorAll('[data-move-signal]').forEach(el=>el.disabled=Number(el.dataset.moveSignal)+Number(el.dataset.direction)<0||Number(el.dataset.moveSignal)+Number(el.dataset.direction)>4);$('[data-action="run-signal"]').disabled=false;save();updateProgress();return;}
  const t=L.signalTiles[order[i]];if(t.icon)$('#signal-leds').innerHTML=led(t.icon);$('#signal-status').innerHTML=bi(`${i+1} / 5 · ${t.en}`,`${i+1} / 5 · ${t.ko}`);i++;timer=setTimeout(advance,650);
 }advance();
}
function teamGroup(){return L.groupValue(s.fields.radioGroup??23);}
function groupPicker(){return `<div class="group-picker"><label class="field">${bi('Our radio group · teacher assigned','우리 팀의 무선 그룹 · 선생님이 정해요')}<input data-radio-group type="number" min="0" max="255" value="${teamGroup()}" inputmode="numeric" aria-describedby="group-help"></label><div><p id="group-help" class="small">${bi('Use this SAME number in on start on BOTH boards. Other teams need their own group.','두 기기의 on start에 이 숫자를 똑같이 넣어요. 다른 팀은 다른 그룹을 사용해요.')}</p><p class="caption">${bi('Changing this box changes the guide and downloaded source projects—not the code already on your boards.','이 칸을 바꾸면 안내와 내려받을 시작 파일만 바뀌어요. 기기에 이미 넣은 코드는 바뀌지 않아요.')}</p></div></div>`;}
function radioFlow(level){return `<div class="radio-flow"><section class="radio-device"><p class="eyebrow">CONTROLLER</p><strong>${bi('Sender','송신기')}</strong><div class="radio-keyline"><span class="keycap">A</span><code>HELP</code></div>${level===2?'<div class="radio-keyline"><span class="keycap">B</span><code>SAFE</code></div>':''}</section><div class="wireless-arrow" aria-hidden="true">⇢</div><section class="radio-device receiver"><p class="eyebrow">BEACON</p><strong>${bi('Receiver','수신기')}</strong><p class="small">${bi('HELP → two flashes + tick','HELP → 두 번 깜박이고 체크 표시')}</p>${level===2?`<p class="small">${bi('SAFE → heart','SAFE → 하트')}</p>`:''}</section></div>`;}
function radioBlock(text){return `<div class="block radio-block">${esc(text)}</div>`;}
function radioStartBlock(){return `<div class="block-onstart">on start<div class="block-body start-body">${radioBlock('radio set group '+teamGroup())}${blockIcon('tick')}</div></div>`;}
function receiveGuide(level,compact=false){
 const flash=compact?`<div class="reuse-stack">${bi('Move your two-flash sequence here. Keep the final tick.','두 번 깜박이는 순서를 여기로 옮겨요. 마지막 체크 표시도 넣어요.')}</div>`:flashBlocks()+flashBlocks()+blockIcon('tick');
 return `<div class="block-guide"><p class="caption">${bi('Receiver block guide · not a live editor','수신기 블록 안내 · 실제 편집기가 아니에요')}</p>${radioStartBlock()}<div class="block-radio-event"><div class="event-label">on radio received <code>receivedString</code></div><div class="receive-body"><div class="block-if"><div class="condition">if <code>receivedString = "HELP"</code> then</div>${flash}${level===2?`<div class="condition">else if <code>receivedString = "SAFE"</code> then</div>${blockIcon('heart')}`:''}</div></div></div></div>`;
}
function senderGuide(level){return `<div class="block-guide"><p class="caption">${bi('Controller block guide · not a live editor','송신기 블록 안내 · 실제 편집기가 아니에요')}</p>${radioStartBlock()}${eventBlock(radioBlock('radio send string "HELP"'))}${level===2?`<div class="block-spacer"></div>${eventBlock(radioBlock('radio send string "SAFE"'),'on button B pressed')}`:''}</div>`;}
function radioHardwareNote(){return `<div class="note amber">${bi('Use two micro:bits. Label them CONTROLLER and BEACON. Keep each powered. Two pairs can share a set.','micro:bit 두 개를 사용해요. CONTROLLER와 BEACON으로 이름표를 붙이고 전원을 켜 두어요. 두 모둠이 함께 사용해도 좋아요.','strong')}${bi('No pair available? Build both projects and explain the message journey with a partner. Record “Peer trace only”, not a successful radio test.','기기 두 개가 없나요? 프로젝트 두 개를 만들고 친구와 메시지 전달 과정을 설명해요. 무선 확인 성공이 아니라 “친구와 따라 보기만 함”으로 기록해요.','p','small')}</div>`;}
function radioEvidence(n){
 return `<section class="panel"><h3>${bi('Record what you really tested','실제로 확인한 내용을 기록해요')}</h3>${radio('radio'+n+'Where',[
 ['hardware',['Two physical boards','실제 기기 두 개']],['trace',['Peer trace only · no hardware radio test','친구와 따라 보기만 함 · 실제 무선 확인 아님']],['help',['Tried on two boards; need help','기기 두 개로 시도함 · 도움 필요']]
 ])}${check('radio'+n+'Tried',n===1?'We tried A → HELP and watched the receiver.':'We tried A → HELP, waited, then B → SAFE.',n===1?'A → HELP를 시도하고 수신기를 살펴봤어요.':'A → HELP를 시도한 뒤 기다렸다가 B → SAFE도 해 봤어요.')}${n===1?check('radio1Repeat','We waited and repeated the test.','기다렸다가 한 번 더 확인했어요.'):check('radio2Both','Both messages gave the expected receiver signals. (Learner report.)','두 메시지 모두 예상한 수신기 신호가 나왔어요. (본인 기록)')}${bi('These are your reports for teacher review. This page cannot read your boards.','선생님과 확인하기 위한 본인 기록이에요. 이 페이지는 기기를 읽을 수 없어요.','p','caption')}</section>`;
}
function radio1Card(part){
 if(part==='sender')return `${where()}${radioFlow(1)}${radioHardwareNote()}${groupPicker()}<div class="two-col guide-layout"><section class="stack">${steps([
 ['Keep your local beacon project. Create another project named W3-Controller.','기존 신호등 프로젝트는 보관해요. W3-Controller라는 새 프로젝트를 만들어요.'],
 ['In on start, add radio set group from Radio. Use your team number.','on start에 Radio의 radio set group을 넣어요. 팀의 숫자를 사용해요.'],
 ['From Input, add on button A pressed. Inside, put radio send string "HELP".','Input에서 on button A pressed를 넣어요. 그 안에 radio send string "HELP"를 넣어요.']
 ])}${check('radio1SenderBuilt','My controller has A → send HELP.','송신기에 A → HELP 보내기를 만들었어요.')}</section>${senderGuide(1)}</div>`;
 if(part==='receiver')return `${where()}${groupPicker()}<div class="two-col guide-layout"><section class="stack">${steps([
 ['Make a copy of your beacon project named W3-Receiver. Add the same radio group in on start.','신호등 프로젝트를 W3-Receiver라는 이름으로 복사해요. on start에 같은 무선 그룹을 넣어요.'],
 ['From Radio, add on radio received receivedString. Inside, put if receivedString = "HELP" from Logic.','Radio에서 on radio received receivedString을 넣어요. 그 안에 Logic으로 if receivedString = "HELP" 조건을 만들어요.'],
 ['Move the flash blocks and tick from the old A event INSIDE this if. Remove the empty old A event.','이전 A 이벤트의 깜박임 블록과 체크 표시를 이 if 안으로 옮겨요. 빈 A 이벤트는 지워요.']
 ])}${check('radio1ReceiverBuilt','My receiver starts the flash sequence when it receives HELP.','수신기에 HELP를 받으면 깜박이는 순서가 시작되도록 만들었어요.')}
 <div class="note">${bi('Need a head start? This receiver starter has the message condition. Add your own flashes.','도움이 필요한가요? 수신기 시작 파일에는 메시지 조건이 있어요. 깜박이는 순서는 직접 추가해요.','p')}<button class="secondary" data-action="project" data-kind="radio-receiver-starter">${bi('Receiver starter (.mkcd)','수신기 시작 파일 (.mkcd)')}</button><p class="caption">${bi('Import as a separate MakeCode project. The starter shows one diamond only.','별도 MakeCode 프로젝트로 가져와요. 시작 파일은 마름모 하나만 보여 줘요.')}</p></div>
 ${details(['Help with if and receivedString','if와 receivedString 도움말'],bi('Open Logic. Place if true then inside the receive event. Replace true with an equality comparison. Drag receivedString from the top of the receive event into the left side; put the text HELP on the right.','Logic을 열어요. 수신 이벤트 안에 if true then을 넣어요. true 대신 같은지 비교하는 조건을 넣어요. 수신 이벤트 위쪽의 receivedString을 왼쪽으로 끌어오고, 오른쪽에는 HELP를 넣어요.','p'))}</section>${receiveGuide(1,true)}</div>`;
 return `${where()}${radioFlow(1)}<div class="two-col"><section class="stack">${steps([
 ['Transfer W3-Controller to CONTROLLER. Transfer W3-Receiver to BEACON.','W3-Controller는 송신기로, W3-Receiver는 수신기로 옮겨요.'],
 ['Press and release A on CONTROLLER. Do not touch the BEACON buttons. Watch for two flashes and a tick.','송신기의 A를 눌렀다 놓아요. 수신기의 버튼은 만지지 말고, 두 번 깜박인 뒤 체크 표시가 나오는지 봐요.'],
 ['Wait until it finishes. Swap the testing role and try again.','끝날 때까지 기다려요. 확인하는 역할을 바꾸고 다시 해 봐요.']
 ])}<button class="secondary" data-action="transfer-help">${bi('Help transferring to my device','내 기기로 전송하는 방법')}</button>${quiz('radioStart')}</section>${radioEvidence(1)}</div>
 <hr><div class="two-col">${quiz('radioGroup')}<section class="panel"><h3>${bi('No response? Check these.','반응이 없나요? 확인해요.')}</h3>${steps([
 ['Both boards are powered, and each has the correct project.','두 기기의 전원이 켜져 있고 각각 알맞은 프로젝트가 들어 있어요.'],
 ['Both radio set group numbers match your team number.','두 radio set group 숫자가 팀의 숫자와 같아요.'],
 ['Both projects use HELP with the exact same letters and capitals.','두 프로젝트 모두 HELP를 같은 글자와 대문자로 사용해요.'],
 ['After editing, transfer the changed program again. Radio messages do not transfer whole programs.','수정한 뒤에는 바뀐 프로그램을 다시 옮겨요. 무선 메시지가 전체 프로그램을 옮기는 것은 아니에요.']
 ])}</section></div>`;
}
function radio2Card(part){
 if(part==='sender')return `${where()}<div class="note">${bi('Keep your working Radio 1 project. Add one new command. Ask for help if your first signal is not ready yet.','잘 작동하는 무선 도전 1 프로젝트는 유지해요. 새 명령 하나를 추가해요. 첫 신호가 아직 준비되지 않았다면 도움을 요청해요.','p')}</div>${radioFlow(2)}${groupPicker()}<div class="two-col guide-layout"><section class="stack">${steps([
 ['Keep A → radio send string "HELP".','A → radio send string "HELP"는 유지해요.'],
 ['Add on button B pressed. Put radio send string "SAFE" inside.','on button B pressed를 추가해요. 그 안에 radio send string "SAFE"를 넣어요.']
 ])}${check('radio2SenderBuilt','My controller sends HELP with A and SAFE with B.','송신기에 A로 HELP, B로 SAFE를 보내도록 만들었어요.')}</section>${senderGuide(2)}</div>`;
 if(part==='receiver')return `${where()}${groupPicker()}<div class="two-col guide-layout"><section class="stack">${steps([
 ['Use the SAME on radio received event. Keep if receivedString = "HELP" and the flashing sequence.','같은 on radio received 이벤트를 사용해요. if receivedString = "HELP"와 깜박이는 순서를 유지해요.'],
 ['Use + on the existing if block to add an else if section. Check receivedString = "SAFE". Inside, show the Heart icon.','기존 if 블록의 +로 else if 부분을 추가해요. receivedString = "SAFE"인지 확인하고, 안에 Heart 아이콘을 넣어요.']
 ])}<div class="note">${bi('Only ONE on radio received string event. Put both message checks inside it.','on radio received string 이벤트는 하나만 만들어요. 그 안에서 두 메시지를 확인해요.','p')}</div>${check('radio2ReceiverBuilt','My receiver checks HELP and SAFE inside one receive event.','수신기의 수신 이벤트 하나 안에서 HELP와 SAFE를 확인하도록 만들었어요.')}</section>${receiveGuide(2,true)}</div>`;
 if(part==='test')return `${where()}${radioFlow(2)}<div class="note">${steps([
 ['Transfer the edited projects to their labelled boards.','수정한 프로젝트를 이름표에 맞는 기기로 옮겨요.'],
 ['Press A on CONTROLLER. HELP should make BEACON flash twice, then show a tick.','송신기의 A를 눌러요. HELP를 받은 수신기가 두 번 깜박인 뒤 체크 표시를 보여야 해요.'],
 ['Wait until the sequence finishes. Press B. SAFE should show a heart on BEACON.','순서가 끝날 때까지 기다려요. B를 눌러요. SAFE를 받은 수신기에 하트가 나와야 해요.']
 ])}<button class="secondary" data-action="transfer-help">${bi('Help transferring to my device','내 기기로 전송하는 방법')}</button><p class="caption">${bi('SAFE is only an LED status message. It is not an emergency stop and does not cancel a running flash sequence.','SAFE는 LED 상태 메시지일 뿐이에요. 비상 정지가 아니며 실행 중인 깜박임을 취소하지 않아요.')}</p></div><div class="two-col">${radioEvidence(2)}<section class="panel"><h3>${bi('Explain the message journey','메시지 전달 과정 설명하기')}</h3>${text('radioExplain','What changes when you press B instead of A?','A 대신 B를 누르면 무엇이 달라지나요?')}${oral('radioExplain')}${bi('“The controller sends ____. The receiver shows ____.”','“송신기가 ____을/를 보내면 수신기에 ____이/가 나와요.”','p','caption')}</section></div>`;
 return `${where()}<div class="two-col"><section>${quiz('radioSpelling')}</section><section class="panel"><h3>${bi('Try a debugging experiment','오류 고치기 실험을 해 봐요')}</h3>${bi('Predict first. With your teacher, try this when your radio signal is working.','먼저 예상해요. 무선 신호가 작동하면 선생님과 함께 해 봐요.','p','small')}${steps([
 ['Change ONLY the sender’s HELP text to HLEP. Predict the result first.','송신기의 HELP만 HLEP로 바꿔요. 먼저 결과를 예상해요.'],
 ['Transfer the changed sender program. Press A once and watch the receiver.','수정한 송신기 코드를 옮겨요. A를 한 번 누르고 수신기를 살펴봐요.'],
 ['Restore HELP. Transfer the sender again. Retest the two-flash response.','HELP로 되돌려요. 송신기에 다시 옮기고 두 번 깜박이는지 확인해요.']
 ])}${bi('One change at a time. Leave the radio group alone. Keep this test at your table.','한 번에 한 가지만 바꿔요. 무선 그룹은 그대로 두고, 자기 책상에서 확인해요.','p','caption')}${text('radioFix','Optional: what did you fix, and what happened next?','선택: 무엇을 고쳤고, 그다음 어떻게 됐나요?')}${oral('radioFix')}${check('radioFixed','We restored HELP and tested again. (Learner report.)','HELP로 고친 뒤 다시 확인했어요. (본인 기록)')}</section></div>`;
}
function sequenceReport(){
 const checks=[
 [['1 · Fix the turn','1 · 회전 명령 고치기'],s.map,s.map.seq.join(' → ')],
 [['2 · Two turns','2 · 두 번 돌기'],s.mapLong,s.mapLong.seq.map(v=>v||'?').join(' → ')],
 [['3 · Order the signal','3 · 신호 순서 만들기'],s.signal,s.signal.order.map(v=>L.signalTiles[v].en).join(' → ')]
 ];
 return `<section><h2>${bi('Main task 1 · Sequencing models','주요 활동 1 · 순서 모형')}</h2>${checks.map(([label,data,seq])=>`<div class="record-item"><h3>${B(label)}</h3><p>${esc(seq)}</p><p>${data.result?bi(data.result.success?'Current sequence passed its model test.':'Current sequence needs another model test after a repair.',data.result.success?'현재 순서가 모형 확인에 성공했어요.':'현재 순서를 고친 뒤 모형에서 다시 확인해야 해요.'):bi('No current model test recorded.','현재 모형 확인 기록이 없어요.')} ${bi(`Recorded attempts: ${data.attempts.length}`,`기록된 시도: ${data.attempts.length}`)}</p></div>`).join('')}<p class="caption">${bi('These are browser-model results, not MakeCode or physical-board tests. Challenges 2–3 are available when ready.','브라우저 모형 결과이며 MakeCode나 실제 기기의 확인 결과가 아니에요. 준비되면 2번과 3번에 도전해요.')}</p></section>`;
}
function radioReport(){
 const modes={hardware:['Two physical boards (learner report)','실제 기기 두 개 (본인 기록)'],trace:['Peer trace only; not a hardware radio test','친구와 따라 보기만 함 · 실제 무선 확인 아님'],help:['Tried on two boards; help needed','기기 두 개로 시도함 · 도움 필요']};
 return `<section><h2>${bi('Main task 2 · Two-board radio','주요 활동 2 · 기기 두 개의 무선 통신')}</h2><dl><dt>${bi('Team group','팀 그룹')}</dt><dd>${teamGroup()}</dd><dt>${bi('Radio 1 · HELP','무선 도전 1 · HELP')}</dt><dd>${B(modes[s.fields.radio1Where]||['Not attempted / not recorded.','아직 시도하거나 기록하지 않았어요.'])} ${bi(s.checks.radio1Tried?'Test attempt reported.':'Test attempt not reported.',s.checks.radio1Tried?'시도했다고 기록했어요.':'시도한 기록이 없어요.')} ${s.checks.radio1Repeat?bi('Repeat attempt reported.','반복 시도를 기록했어요.'):''}</dd><dt>${bi('Radio 2 · HELP / SAFE','무선 도전 2 · HELP / SAFE')}</dt><dd>${B(modes[s.fields.radio2Where]||['Not attempted / not recorded.','아직 시도하거나 기록하지 않았어요.'])} ${s.checks.radio2Both?bi('Both expected responses reported.','예상한 두 응답이 나왔다고 기록했어요.'):bi('Both expected responses not yet reported.','예상한 두 응답을 아직 기록하지 않았어요.')}</dd><dt>${bi('Message explanation','메시지 설명')}</dt><dd>${response('radioExplain')}</dd><dt>${bi('Debugging explanation','오류 고치기 설명')}</dt><dd>${response('radioFix')}</dd><dt>${bi('Restored and retested','고친 뒤 다시 확인')}</dt><dd>${bi(s.checks.radioFixed?'Reported.':'Not reported.',s.checks.radioFixed?'기록했어요.':'기록하지 않았어요.')}</dd></dl><p class="caption">${bi('Off-page programming and hardware results are learner reports. This lesson cannot inspect or certify a micro:bit program. Radio 2 is a readiness challenge.','다른 페이지의 코딩과 실제 기기 결과는 본인 기록이에요. 이 수업은 micro:bit 프로그램을 검사하거나 인증할 수 없어요. 준비되면 무선 도전 2에 도전해요.')}</p></section>`;
}

function editorTour(){
 const items=[['▦',['Simulator','시뮬레이터'],['Press its A button to test your code.','A 버튼을 눌러 코드를 확인해요.']],['▤',['Toolbox','블록 목록'],['Find Input for buttons. Find Basic for pictures and pauses.','Input에서 버튼을, Basic에서 그림과 기다리기 블록을 찾아요.']],['▰',['Workspace','작업 공간'],['Snap blocks inside the event. Read from top to bottom.','이벤트 안에 블록을 붙여요. 위에서 아래로 읽어요.']],['↓',['Download','코드 내려받기'],['Transfer the tested program to your micro:bit later in this lesson.','나중에 확인한 프로그램을 micro:bit로 옮겨요.']]];
 return `<section class="panel"><h3>${bi('Find these in MakeCode','MakeCode에서 찾아보세요')}</h3><p class="caption">${bi('Layout guide, not a live editor. Tablet layouts may look different.','위치 안내이며 실제 편집기가 아니에요. 태블릿에서는 배치가 다를 수 있어요.')}</p><div class="editor-places">${items.map(([icon,title,desc])=>`<div class="editor-place"><span class="place-symbol" aria-hidden="true">${icon}</span><div><strong>${B(title)}</strong>${B(desc,'p','small')}</div></div>`).join('')}</div></section>`;
}
function editorCard(){return `${where()}<div class="two-col"><div class="stack">${steps([['Choose New Project. Name it Week3-Beacon. Keep Blocks selected.','New Project를 선택하고 이름을 Week3-Beacon으로 정해요. Blocks를 선택해요.'],['Remove the unused forever block. Open Input and drag on button A pressed into the workspace.','쓰지 않는 forever 블록을 없애요. Input을 열고 on button A pressed를 작업 공간으로 가져와요.'],['Open Basic. Put show icon inside the A event and choose the diamond picture.','Basic을 열어요. A 이벤트 안에 show icon을 넣고 마름모 그림을 골라요.'],['Press and release A in the MakeCode simulator. Does the diamond appear?','MakeCode 시뮬레이터에서 A를 눌렀다 놓아요. 마름모가 나타나나요?']])}${check('editorA','My Button A shows a diamond in MakeCode.','MakeCode에서 A 버튼을 누르면 마름모가 나타나요.')}${details(['Need a starting project?','시작 파일이 필요한가요?'],`<p>${bi('This starter only shows one picture. You will build the blinking sequence yourself.','이 시작 파일은 그림 하나만 보여 줘요. 깜박이는 순서는 직접 만들 거예요.')}</p><button class="secondary" data-action="project" data-kind="starter">${bi('Download editable starter (.mkcd)','편집할 시작 파일 내려받기 (.mkcd)')}</button><p class="caption" style="margin-top:12px">${bi('MakeCode Home → Import → Import File. Choose the .mkcd file. If importing is unavailable, build the three blocks above instead.','MakeCode 첫 화면에서 Import → Import File을 선택하고 .mkcd 파일을 열어요. 가져오기가 안 되면 위의 블록을 직접 만들어요.')}</p>`)}</div><div class="stack">${editorTour()}${blockGuide('starter')}</div></div>`;}
function beaconCard(buildStep){let body='';
 if(buildStep===0)body=`<div class="two-col guide-layout"><div class="stack"><h3>${bi('Add a visible dark gap.','불이 꺼지는 시간을 넣어요.')}</h3>${steps([['Keep show icon (diamond) inside the A event.','A 이벤트 안의 show icon (마름모)을 그대로 두어요.'],['Below it, add pause (ms) from Basic. Set it to 500.','그 아래에 Basic의 pause (ms)를 넣고 500으로 정해요.'],['Add clear screen, then another pause (ms) 500. Look in Basic, or its More section.','clear screen을 넣고 pause (ms) 500을 하나 더 넣어요. Basic 또는 그 안의 More에서 찾아요.'],['Test in MakeCode: A should show a diamond, then leave the screen dark.','MakeCode에서 확인해요. A를 누르면 마름모가 나타난 뒤 화면이 꺼져 있어야 해요.']])}<div class="note">${bi('500 milliseconds is half a second. The pause after clear screen lets us notice the dark gap.','500밀리초는 0.5초예요. clear screen 뒤의 pause 덕분에 불이 꺼진 시간을 볼 수 있어요.','p')}</div>${check('oneFlash','I made one flash in MakeCode.','MakeCode에서 한 번 깜박이게 만들었어요.')}</div>${blockGuide('one')}</div>`;
 if(buildStep===1)body=`<div class="two-col guide-layout"><div class="stack"><h3>${bi('Build the same four blocks again.','같은 네 블록을 한 번 더 만들어요.')}</h3>${steps([['Under the first four blocks, add another diamond → pause 500 → clear screen → pause 500.','처음 네 블록 아래에 마름모 → pause 500 → clear screen → pause 500을 한 번 더 넣어요.'],['At the very end, add show icon and choose the tick (Yes).','맨 끝에 show icon을 넣고 체크 표시 (Yes)를 골라요.'],['Put another tick inside on start. It shows the beacon is ready when the program begins.','on start 안에도 체크 표시를 넣어요. 프로그램이 시작되면 준비됐다는 표시가 나와요.']])}<div class="block-onstart">on start<div class="block-body" style="border-color:var(--blue);margin-top:9px">${blockIcon('tick')}</div></div>${bi('Read downward: light → wait → dark → wait → light → wait → dark → wait → tick.','위에서 아래로 읽어요. 켜기 → 기다리기 → 끄기 → 기다리기 → 켜기 → 기다리기 → 끄기 → 기다리기 → 체크 표시.','p','small')}${check('twoFlashBuilt','I added the second flash and the final tick.','두 번째 깜박임과 마지막 체크 표시를 넣었어요.')}${details(['I need a smaller first goal','더 작은 목표부터 할래요'],bi('Make one flash, then add the final tick. Show it to your teacher before adding the second flash.','한 번 깜박인 뒤 체크 표시가 나오게 만들어요. 선생님께 보여 드린 후 두 번째 깜박임을 추가해요.','p'))}</div>${blockGuide('full')}</div>`;
 if(buildStep===2)body=`<div class="two-col"><div><h3>${bi('Try your own A button.','직접 만든 A 버튼을 눌러요.')}</h3>${signalStrip()}${steps([['In MakeCode, press and release A once.','MakeCode에서 A를 한 번 눌렀다 놓아요.'],['Count two diamond flashes. Check for a dark gap between them.','마름모가 두 번 깜박이는지 세어 봐요. 사이에 꺼지는 시간이 있는지 확인해요.'],['Wait for the tick. Then press A again to check it repeats the same sequence.','체크 표시가 나올 때까지 기다려요. 그다음 A를 눌러 같은 순서로 실행되는지 확인해요.']])}${check('beaconTest','I tested my beacon in MakeCode: flash, gap, flash, gap, tick.','MakeCode에서 깜박임, 꺼짐, 깜박임, 꺼짐, 체크 표시를 확인했어요.')}${details(['My program looks wrong','프로그램이 이상해요'],`<p>${bi('No picture? Check that all blocks are snapped inside the A event. No gap? Add clear screen followed by pause. Never finishes? Make sure these blocks are not in forever.','그림이 안 나오나요? 모든 블록이 A 이벤트 안에 붙어 있는지 봐요. 꺼지는 시간이 없나요? clear screen 다음에 pause를 넣어요. 끝나지 않나요? forever 안에 넣지 않았는지 봐요.')}</p>`)}</div><div>${quiz('gap')}</div></div>`;
 return `${where()}${body}${bi('This is an LED signal, not a motor program or an emergency stop. Wait for the tick before pressing A again.','이것은 LED 신호이며 모터 프로그램이나 비상 정지 기능이 아니에요. 체크 표시가 나온 뒤 A를 다시 눌러요.','p','caption')}`;
}
function transferInstructions(){const device=s.profile.device,noBoard=s.profile.board==='none'||device==='simulator';if(noBoard)return `<div class="note amber">${bi('Simulator-only today: finish the same program in MakeCode. Record “No physical board used”.','오늘은 시뮬레이터만 사용해요. MakeCode에서 같은 프로그램을 완성하고 “실제 기기는 사용하지 않음”으로 기록해요.','p')}${bi('A teacher transfer station can be used later. Do not count an on-screen test as a board test.','나중에 선생님의 전송용 컴퓨터를 사용할 수 있어요. 화면에서 확인한 것을 실제 기기 확인으로 기록하지 않아요.','p','small')}</div>`;
 const instructions={
 computer:[['Connect the micro:bit with a USB data cable. Ask for help if the cable only charges.','USB 데이터 케이블로 micro:bit를 연결해요. 충전만 되는 케이블이면 도움을 요청해요.'],['In MakeCode choose Download. Follow the browser’s pairing and transfer instructions.','MakeCode에서 Download를 선택하고 브라우저의 연결·전송 안내를 따라요.'],['If a .hex file is downloaded instead, save it and copy it onto the MICROBIT drive. A .mkcd starter is not the file to copy.','.hex 파일이 내려받아지면 저장한 뒤 MICROBIT 드라이브로 복사해요. .mkcd 시작 파일을 복사하는 것이 아니에요.'],['Wait for transfer to finish and your tick to appear. Press and release the real A button.','전송이 끝나고 체크 표시가 나올 때까지 기다려요. 실제 A 버튼을 눌렀다 놓아요.']],
 ipad:[['Use the official micro:bit iOS app to transfer by Bluetooth. Ask your teacher to check the app is ready.','공식 micro:bit iOS 앱을 사용해 블루투스로 옮겨요. 선생님께 앱이 준비됐는지 확인받아요.'],['Open your MakeCode project inside the app, or use the app to transfer the file from your browser project.','앱 안에서 MakeCode 프로젝트를 열거나 브라우저에서 만든 파일을 앱으로 옮겨요.'],['Follow the app’s pairing and flashing instructions with your teacher. Do not use the laptop USB-copy steps on iPad.','선생님과 앱의 페어링·전송 안내를 따라요. iPad에서는 노트북의 USB 복사 방법을 쓰지 않아요.'],['When the tick appears, press and release the real A button.','체크 표시가 나오면 실제 A 버튼을 눌렀다 놓아요.']],
 android:[['Ask your teacher to connect a suitable USB data cable or adapter to the Android device.','선생님께 안드로이드 기기에 알맞은 USB 데이터 케이블이나 어댑터를 연결해 달라고 해요.'],['Use MakeCode in Chrome or Edge. Choose Download and follow its connection and transfer instructions.','Chrome 또는 Edge에서 MakeCode를 사용해요. Download를 선택하고 연결·전송 안내를 따라요.'],['The official micro:bit Android app is another route when set up by your teacher. Ask for the school’s preferred method.','선생님이 준비한 공식 micro:bit Android 앱을 사용할 수도 있어요. 학교에서 사용할 방법을 물어보세요.'],['Wait for transfer to finish. When your tick appears, test the real A button.','전송이 끝날 때까지 기다려요. 체크 표시가 나오면 실제 A 버튼을 확인해요.']]
 };
 return steps(instructions[device]||instructions.computer)+`<p class="caption" style="margin-top:16px"><a href="https://microbit.org/get-started/user-guide/transfer-code-to-the-microbit/" target="_blank" rel="noopener noreferrer">${bi('Official transfer guide ↗','공식 코드 전송 안내 ↗')}</a></p>`;
}
function transferCard(){return `${where()}<div class="two-col"><div><label class="field">${bi('Show instructions for my device','내 기기의 안내 보기')}<select data-profile="device">${deviceOptions(s.profile.device)}</select></label><label class="field">${bi('Board available today','오늘 사용할 기기')}<select data-profile="board">${option('pair','Two boards for our team · 우리 팀에 기기 두 개',s.profile.board)}${option('shared','Shared micro:bit · 함께 사용하는 micro:bit',s.profile.board)}${option('own','My own micro:bit · 혼자 사용하는 micro:bit',s.profile.board)}${option('none','No physical micro:bit · 실제 micro:bit 없음',s.profile.board)}</select></label>${transferInstructions()}<div class="note amber">${bi('Hold the board by its edges. Keep the cable loose and wait until transfer finishes before unplugging. Ask for help rather than changing device settings yourself.','기기의 가장자리를 잡아요. 케이블을 팽팽하게 당기지 말고 전송이 끝나기 전에 뽑지 않아요. 기기 설정을 직접 바꾸지 말고 도움을 요청해요.','p')}</div></div><div class="panel"><h3>${bi('Test YOUR program.','직접 만든 프로그램을 확인해요.')}</h3>${check('simulatorTest','I tested my own program in the MakeCode simulator.','MakeCode 시뮬레이터에서 직접 만든 프로그램을 확인했어요.')}<h4>${bi('What happened on the physical board?','실제 기기에서는 어떻게 됐나요?')}</h4>${radio('physical',[['worked',['Two flashes and a tick worked.','두 번 깜박이고 체크 표시가 나왔어요.']],['one',['One flash and a tick worked.','한 번 깜박이고 체크 표시가 나왔어요.']],['help',['I tried, but I need help.','시도했지만 도움이 필요해요.']],['notUsed',['No physical board used.','실제 기기는 사용하지 않았어요.']]])}${bi('These are your reports, not an automatic check of the device.','이것은 여러분의 기록이며 기기를 자동으로 확인한 결과가 아니에요.','p','caption')}${details(['Nothing appeared on my micro:bit','micro:bit에 아무것도 나타나지 않아요'],bi('Check power and the data cable with your teacher. Confirm that the correct project was downloaded and the transfer finished. If needed, use a teacher transfer station while your partner continues coding.','선생님과 전원과 데이터 케이블을 확인해요. 올바른 프로젝트를 내려받았는지, 전송이 끝났는지 봐요. 필요하면 친구는 코딩을 계속하고 선생님의 전송용 컴퓨터를 사용해요.','p'))}</div></div>`;}
function playInstructions(){switch(s.fields.changeChoice){
 case 'timing':return `<h3>${bi('Make the beacon slower.','신호를 더 천천히 만들어요.')}</h3>${steps([['Predict what will happen if the pauses are longer.','기다리는 시간이 길어지면 어떻게 될지 예상해요.'],['Change all four pause values from 500 to 1000. Leave the pictures and order unchanged.','네 개의 pause 값을 모두 500에서 1000으로 바꿔요. 그림과 순서는 그대로 두어요.'],['Press A in MakeCode. Compare with the first version. Then transfer again to test on your board.','MakeCode에서 A를 눌러 처음과 비교해요. 실제 기기에서 확인하려면 다시 전송해요.']])}<div class="note">${bi('1000 ms is 1 second. The icon blocks also take time, so the whole program is longer than just the sum of the pauses.','1000밀리초는 1초예요. 아이콘 블록에도 시간이 걸리므로 프로그램 전체 시간은 pause를 더한 것보다 길어요.','p')}</div>`;
 case 'symbol':return `<h3>${bi('Invent your own rescue symbol.','나만의 구조 표시를 만들어요.')}</h3>${steps([['In Basic, find show leds. Click its squares to draw a simple team symbol.','Basic에서 show leds를 찾아요. 작은 칸을 눌러 간단한 팀 표시를 그려요.'],['Replace BOTH diamond blocks with your show leds picture. Keep the clear-screen blocks and pauses.','두 개의 마름모 블록을 모두 만든 show leds 그림으로 바꿔요. clear screen과 pause는 그대로 두어요.'],['Test it. Ask your partner what the picture means. Transfer again to see it on the board.','확인해요. 친구에게 그림의 뜻을 물어봐요. 실제 기기에서 보려면 다시 전송해요.']])}`;
 case 'buttonB':return `<h3>${bi('Give Button B its own job.','B 버튼에 다른 역할을 줘요.')}</h3>${steps([['Add a separate on button pressed event from Input. Change its letter to B.','Input에서 on button pressed 이벤트를 따로 추가하고 글자를 B로 바꿔요.'],['Put show icon (heart) inside B. This can be your team badge. Do not move the A blocks.','B 안에 show icon (하트)을 넣어요. 팀 배지로 사용할 수 있어요. A의 블록은 옮기지 않아요.'],['Let A finish, then press B. Transfer again and test both buttons on the board.','A의 실행이 끝난 뒤 B를 눌러요. 다시 전송하고 실제 기기에서 두 버튼을 확인해요.']])}<div class="block-guide" style="margin-top:18px">${eventBlock(blockIcon('heart'),'on button B pressed')}</div><p class="caption">${bi('B changes the display. It is not an emergency stop and does not cancel a running A sequence.','B는 화면을 바꿔요. 비상 정지 기능이 아니며 실행 중인 A의 명령을 취소하지 않아요.')}</p>`;
 default:return `<div class="note">${bi('Choose ONE experiment. Make a prediction, then change your real MakeCode program.','실험을 하나만 골라요. 결과를 예상한 뒤 실제 MakeCode 프로그램을 바꿔요.','p')}</div>`;
}}
function playCard(){return `${where()}<div class="note">${bi('Choose ONE experiment below. These are choices, not extra steps. Next will always take you to Radio 1.','아래에서 실험 하나만 골라요. 세 가지를 모두 할 필요는 없어요. 다음 버튼을 누르면 무선 도전 1로 가요.','p')}</div>${check('rolesSwapped','We swapped roles. Both of us will change code. (Working alone? Take both roles.)','역할을 바꿨어요. 두 사람 모두 코드를 바꿀 거예요. 혼자라면 두 역할을 모두 해요.')}<div class="actions">${radio('changeChoice',[['timing',['Slower signal','더 느린 신호']],['symbol',['My own symbol','나만의 그림']],['buttonB',['Add Button B','B 버튼 추가']]])}</div><div class="two-col"><div>${playInstructions()}</div><div class="panel"><h3>${bi('Predict → change → test','예상 → 바꾸기 → 확인')}</h3>${text('prediction','I think my change will… (or tell your partner)','바꾸면 이렇게 될 것 같아요… (친구에게 말해도 돼요)')}${check('changeRetest','I changed my program and tested the new version.','프로그램을 바꾸고 새 버전을 확인했어요.')}<h4>${bi('Where did you test the change?','바꾼 코드를 어디에서 확인했나요?')}</h4>${radio('changeWhere',[['simulator',['MakeCode simulator','MakeCode 시뮬레이터']],['board',['Physical micro:bit','실제 micro:bit']],['both',['Both','둘 다']]])}${text('change','I changed ____. Now it ____.','____을/를 바꿨어요. 이제 ____.')}${oral('change')}${bi('One thoughtful change is enough. Keep building and testing instead of filling in lots of text.','생각해서 바꾼 한 가지면 충분해요. 글을 많이 쓰기보다 계속 만들고 확인해요.','p','caption')}</div></div>`;}
function pitCard(){return `<div class="two-col"><div>${radio('phase',[['drowning',['Drowning · Help me find the first block.','첫 블록을 찾는 데 도움이 필요해요.']],['new',['New Learning · I can make one flash with help.','도움을 받으면 한 번 깜박이게 만들 수 있어요.']],['consolidating',['Consolidating · I can test and change my signal.','신호를 확인하고 바꿀 수 있어요.']],['treading',['Treading Water · I am ready for a new challenge.','새로운 도전을 할 준비가 됐어요.']]])}</div><div class="panel"><h3>${bi('Point. Show. Explain.','가리키고, 보여 주고, 설명해요.')}</h3>${steps([['Point to the event that starts your signal.','신호를 시작하는 이벤트를 가리켜요.'],['Show a pause or a block you changed.','pause 또는 바꾼 블록을 보여 줘요.'],['Explain what happened—in English, Korean or both.','무슨 일이 일어났는지 영어, 한국어 또는 두 언어로 설명해요.']])}${check('pitShow','I showed my program and explained my next step.','프로그램을 보여 주고 다음 단계를 설명했어요.')}<button class="secondary" data-action="words">${bi('Help me explain','설명 도움말')}</button></div></div>${details(['School Learning Pit Stop picture','학교의 배움 점검 그림'],`<img src="assets/learning-pitstop.jpg" alt="School Learning Pit Stop. Plain English and Korean descriptions are provided above." loading="lazy">`)}`;}
function extensionCard(){let extra='';if(s.fields.extension==='repeat')extra=`<div class="two-col"><div><h3>${bi('Same signal. Fewer repeated blocks.','같은 신호를 반복 블록으로 만들어요.')}</h3>${steps([['In Loops, find repeat 4 times. Change 4 to 2.','Loops에서 repeat 4 times를 찾아 4를 2로 바꿔요.'],['Inside it, place diamond → pause 500 → clear screen → pause 500. Remove the other copied flash section.','그 안에 마름모 → pause 500 → clear screen → pause 500을 넣어요. 복사해 둔 다른 깜박임 부분은 없애요.'],['Keep the final tick AFTER the repeat block, but still inside A. Test: do you still get two flashes then a tick?','마지막 체크 표시는 반복 블록 다음에 두되 A 이벤트 안에 있어야 해요. 여전히 두 번 깜박인 뒤 체크 표시가 나오나요?']])}</div>${blockGuide('repeat')}</div>`;
 else if(s.fields.extension==='shake')extra=`<div class="two-col"><div><h3>${bi('Try a different input.','다른 입력을 사용해요.')}</h3>${steps([['In Input, add on shake as a separate event.','Input에서 on shake 이벤트를 따로 추가해요.'],['Put a show icon block inside it. Choose a picture you want.','그 안에 show icon을 넣고 원하는 그림을 골라요.'],['After A finishes, gently shake the board to show the new picture. Keep the cable loose, or ask your teacher for a suitable battery pack.','A의 실행이 끝나면 기기를 살짝 흔들어 새 그림을 보여 줘요. 케이블을 팽팽하게 당기지 말고 필요하면 선생님께 알맞은 배터리 팩을 요청해요.']])}<p class="caption">${bi('In the MakeCode simulator, use its shake control. This only changes the local display; it sends no radio message.','MakeCode 시뮬레이터에서는 흔들기 조작을 사용해요. 이 기능은 기기의 화면만 바꾸며 무선 메시지를 보내지 않아요.')}</p></div>${blockGuide('shake')}</div>`;
 else if(s.fields.extension==='secure')extra=`<div class="panel"><h3>${bi('Make one clear flash you can explain.','설명할 수 있는 깜박임 하나를 만들어요.')}</h3>${bi('Use diamond → pause → clear screen → pause → tick. Put it inside A, test it, and show which block makes the dark gap. Then try adding a second flash.','A 안에 마름모 → pause → clear screen → pause → 체크 표시를 넣어요. 실행하고 어떤 블록이 꺼지는 시간을 만드는지 보여 줘요. 그다음 두 번째 깜박임에 도전해요.','p')}</div>`;
 return `${where()}<div class="note">${bi('Choose ONE next step to try here. Then use Next to reach the plenary.','여기서 해 볼 활동 하나만 골라요. 그다음 아래의 다음 버튼을 눌러 마무리로 가요.','p')}</div>${radio('extension',[['secure',['Make my first signal reliable','첫 신호 확실히 익히기']],['repeat',['Use a repeat block','반복 블록 사용하기']],['shake',['Try a shake input','흔들기 입력 사용하기']]])}<div style="margin-top:22px">${extra}</div>${check('extensionTried','I tried my chosen next step in MakeCode.','고른 다음 단계를 MakeCode에서 해 봤어요.')}`;
}
function plenaryCard(){return `<div class="two-col"><div>${quiz('exit')}<div class="note">${bi('We tested an LED signal today. Robot motors still need their own building and testing session.','오늘은 LED 신호를 확인했어요. 로봇 모터를 조립하고 확인하는 시간은 따로 필요해요.','p')}</div></div><div class="panel"><h3>${bi('Show your work. Save it.','활동을 보여 주고 저장해요.')}</h3>${text('final','One block I used—and what it does…','사용한 블록 하나와 그 블록이 하는 일…')}${oral('final')}${check('projectSaved','I saved my Week3-Beacon project or asked my teacher to help.','Week3-Beacon 프로젝트를 저장했거나 선생님께 도움을 요청했어요.')}<label class="field">${bi('Optional: project link or where you saved it','선택: 프로젝트 링크 또는 저장한 곳')}<input type="text" data-field="projectLocation" maxlength="400" value="${esc(s.fields.projectLocation||'')}" autocomplete="off"></label><div class="actions"><button class="primary" data-action="record">${bi('View / save my learning record','배움 기록 보기 / 저장하기')}</button><button class="secondary" data-action="words">${bi('Help me explain','설명 도움말')}</button></div>${bi('Your learning record is separate from your actual MakeCode project. Keep both.','배움 기록과 실제 MakeCode 프로젝트는 서로 달라요. 둘 다 보관해요.','p','caption')}</div></div>`;
}
function toast(en,ko){const el=$('#toast');el.innerHTML=bi(en,ko);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
function openDialog(title,body){const d=$('#dialog');d.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${B(title)}</h2><button class="secondary" data-action="close" aria-label="Close / 닫기">✕</button></header><div class="dialog-content">${body}</div>`;if(!d.open)d.showModal();}
function words(){openDialog(['Words & help to explain','단어와 설명 도움말'],`<div class="two-col"><div>${C.words.map(([w,m])=>`<div class="panel" style="margin-bottom:12px"><h3>${B(w)}</h3>${B(m,'p','no-margin')}</div>`).join('')}</div><div class="stack"><section class="panel navy"><h3>${bi('Use your languages.','편한 언어를 사용해요.')}</h3>${bi('Think, talk, point and explain in English, Korean or both. The programming challenge stays the same.','영어, 한국어 또는 두 언어로 생각하고 말하고 가리키며 설명해요. 코딩 과제는 같아요.','p')}</section>${[['First ____. Next ____. Finally ____.','먼저 ____. 다음에 ____. 마지막으로 ____.'],['I changed ____. Now the signal ____.','____을/를 바꿨어요. 이제 신호가 ____.'],['The pause makes it ____.','pause 때문에 ____해요.'],['I tested it in the simulator / on the board.','시뮬레이터 / 실제 기기에서 확인했어요.'],['The controller sends ____. The receiver shows ____.','송신기가 ____을/를 보내면 수신기에 ____이/가 나와요.']].map(p=>`<section class="panel">${B(p,'p','no-margin')}</section>`).join('')}${bi('Block labels remain in English in these guides. You can use Korean to explain what they do.','이 안내의 블록 이름은 영어로 유지돼요. 블록이 하는 일은 한국어로 설명해도 좋아요.','p','caption')}</div></div>`);}
function tools(){openDialog(['Lesson tools','수업 도구'],`<div class="actions">${mcLink()}<button class="secondary" data-action="words">${bi('Word & language help','단어와 설명 도움말')}</button><button class="secondary" data-action="record">${bi('My learning record','내 배움 기록')}</button>${s.profile.teacher?'<button class="secondary" data-action="early-extension">Teacher jump: extension</button>':''}</div><div class="note">${bi('Use the same Next button for every step. Back returns to the previous step. Close this help panel to carry on where you were. Checks are records, not marks.','모든 단계에서 같은 다음 버튼을 사용해요. 이전 버튼은 바로 전 단계로 돌아가요. 이 도움말을 닫으면 하던 단계에서 이어서 해요. 체크 표시는 기록이며 점수가 아니에요.','p')}</div><div class="two-col"><div><h3>${bi('Keep your code editable','코드를 나중에도 바꿀 수 있게 해요')}</h3><button class="secondary" data-action="project" data-kind="starter">${bi('Editable starter (.mkcd)','편집 가능한 시작 파일 (.mkcd)')}</button>${bi('Import this into MakeCode. Compile/download from MakeCode before transferring to a board.','MakeCode로 가져온 뒤 기기로 옮기기 전에 MakeCode에서 내려받아요.','p','caption')}<button class="ghost" data-action="signout">${bi('Save and return to sign-in','저장하고 시작 화면으로 돌아가기')}</button></div><div><h3>${bi('Privacy & saving','개인정보와 저장')}</h3>${bi('Names, responses and checks are stored only in this browser. Nothing is uploaded by this lesson. Opening MakeCode or a guide opens an external service. Export a record before using another browser or clearing its data.','이름, 답변, 체크 표시는 이 브라우저에만 저장돼요. 이 수업은 데이터를 업로드하지 않아요. MakeCode나 안내 링크는 외부 서비스를 열어요. 브라우저를 바꾸거나 데이터를 지우기 전에 기록을 내려받아요.','p','small')}</div></div>${s.profile.teacher?`<hr><h3>Teacher controls</h3><div class="actions"><button class="primary" data-action="guide">90-minute teacher guide</button><button class="secondary" data-action="project" data-kind="demo">Complete demonstration (.mkcd)</button><button class="secondary" data-action="project" data-kind="repeat">Repeat version (.mkcd)</button><button class="secondary" data-action="project" data-kind="radio-controller-1">Radio 1 · Controller (.mkcd)</button><button class="secondary" data-action="project" data-kind="radio-receiver-1">Radio 1 · Receiver (.mkcd)</button><button class="secondary" data-action="project" data-kind="radio-controller-2">Radio 2 · Controller (.mkcd)</button><button class="secondary" data-action="project" data-kind="radio-receiver-2">Radio 2 · Receiver (.mkcd)</button></div><p class="caption">Teacher mode opens notes and model projects. It is not a password-protected system, does not read other pupils’ records, and does not certify their work.</p>`:''}${details(['Official technical guidance','공식 기술 안내'],`<p class="caption">Device guidance checked 16 September 2026. The curriculum adaptation is teacher-designed.</p>${C.sources.map(([name,url])=>`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a></p>`).join('')}`)}`);}
function teacherGuide(){let elapsed=0;openDialog(['Teacher guide · 90 minutes','교사 안내 · 90분'],`<div class="note"><strong>22 linear screens · 90 minutes. One fixed Back/Next path.</strong><p>Every sequence challenge, beacon-building step and radio stage appears in order. No student activity tabs or jump menu. Teacher review keeps direct jumping. Transfer help opens in place rather than sending pupils to an earlier activity.</p><p>15 minutes for the three sequence screens; 49 minutes for MakeCode, transfer, experimenting and radio. Support is available throughout. Pupils see every step even when they need help, and Next never requires a correct answer to unlock. Use teacher judgement to pace or defer a challenge. No maps in Main task 2 and no compulsory functions.</p></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Stage</th><th>Focus</th></tr></thead><tbody>${C.cards.map(c=>{const start=elapsed;elapsed+=c.mins;return `<tr><td>${start}–${elapsed}</td><td>${esc(c.stage[0])}</td><td><strong>${esc(c.title[0])}</strong><p>${esc(c.teacher)}</p></td></tr>`;}).join('')}</tbody></table></div><h3>Before pupils arrive</h3><p>Check MakeCode access, data cables, board power, any school device restrictions, and iPad/Android app readiness. Prepare a teacher transfer station. Import and compile the supplied source projects on your school setup before class; live MakeCode importing and physical flashing could not be verified in the build environment.</p><p>Students keep the actual MakeCode program separately from the exported learning record. All off-page editor/hardware evidence is learner-reported. The three sequence models are automatically evaluated; real MakeCode and radio tests are learner reports. Prepare two powered, labelled micro:bits per team, with distinct teacher-assigned groups. HELP/SAFE is a new LED-message protocol, not a change to the earlier movement vocabulary.</p><div class="actions"><button class="secondary" data-action="project" data-kind="demo">Complete demonstration (.mkcd)</button><button class="secondary" data-action="project" data-kind="repeat">Repeat demonstration (.mkcd)</button></div><h3>Timing detail</h3><p>MakeCode show icon includes a 600 ms default interval in addition to explicit pause blocks. The core lesson asks for observable order and gaps, not exact total program duration. B and shake extensions do not cancel a running A handler; test them after A finishes. No sound, external sensor or motor is required. Radio 2 uses one receive-string event with if/else if. SAFE is only an LED status message; it does not cancel a running sequence. Wait between commands. Radio groups are classroom organisation, not secure private channels.</p>`);}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function projectDownload(kind){
 const names={starter:'W3_Beacon_Starter',demo:'W3_Beacon_Two_Flashes',repeat:'W3_Beacon_Repeat','radio-controller-1':'W3_Radio1_Controller','radio-receiver-1':'W3_Radio1_Receiver','radio-receiver-starter':'W3_Radio_Receiver_Starter','radio-controller-2':'W3_Radio2_Controller','radio-receiver-2':'W3_Radio2_Receiver'};
 kind=names[kind]?kind:'starter';download(names[kind]+'.mkcd',L.project(names[kind],L.source(kind,teamGroup())),'application/json');
 toast('Import this editable project in MakeCode. Check the group, then compile/download for the correct board. This is not a firmware .hex file.','MakeCode로 가져올 편집 가능한 파일이에요. 그룹을 확인하고 알맞은 기기로 내려받아요. .hex 펌웨어 파일이 아니에요.');
}

function response(k){const value=String(s.fields[k]||'').trim();if(value)return esc(value);return s.checks[k+'Oral']?bi('Explained aloud / pointed and demonstrated (learner report; not recorded).','말로 설명하거나 가리키며 보여 줬다고 기록했어요. 녹음한 것은 아니에요.'):bi('Not recorded.','기록하지 않았어요.');}
function report(){const f=s.fields,c=s.checks,p=s.profile,phys={worked:['Two flashes and tick worked.','두 번 깜박인 뒤 체크 표시가 나왔어요.'],one:['One flash and tick worked.','한 번 깜박인 뒤 체크 표시가 나왔어요.'],help:['Tried; help needed.','시도했으며 도움이 필요해요.'],notUsed:['No physical board used.','실제 기기를 사용하지 않았어요.']},change={timing:['Longer pauses','더 긴 기다리기'],symbol:['Own LED symbol','나만의 LED 그림'],buttonB:['Separate Button B event','별도의 B 버튼 이벤트']},test={simulator:['MakeCode simulator','MakeCode 시뮬레이터'],board:['Physical micro:bit','실제 micro:bit'],both:['Simulator and physical board','시뮬레이터와 실제 기기']};
 return `<article class="record"><header class="record-head"><p class="eyebrow">MICROBIT INVENTORS · WEEK 03 · LINEAR EDITION</p><h1>${B(C.title)}</h1><p><strong>${esc(p.name)}</strong> · ${esc(p.klass||'Teacher review')} · ${esc(p.device)}</p><p class="caption">${esc(new Date().toLocaleString())} · ${completedCount()}/${C.cards.length} ${bi('activities with recorded evidence','활동의 기록 완료')}</p>${p.teacher?'<strong>TEACHER PREVIEW — NOT A STUDENT RECORD</strong>':''}</header><section>${B(C.wagba,'p')}<p class="caption">${bi('MakeCode and board checks below are reported by the learner, not automatically inspected. No motor behaviour was tested.','아래의 MakeCode와 실제 기기 확인은 본인 기록이며 자동으로 검사한 것이 아니에요. 모터 동작은 확인하지 않았어요.')}</p></section><section><h2>${bi('My program and tests','내 프로그램과 확인')}</h2><dl><dt>${bi('Button A in MakeCode','MakeCode의 A 버튼')}</dt><dd>${bi(c.editorA?'Picture tested (reported).':'Not recorded.',c.editorA?'그림 확인 완료 (본인 기록).':'기록하지 않았어요.')}</dd><dt>${bi('Two-flash sequence','두 번 깜박이는 순서')}</dt><dd>${bi(c.beaconTest?'Two flashes, dark gaps and tick tested (reported).':'Not recorded.',c.beaconTest?'두 번 깜박임, 꺼짐, 체크 표시 확인 (본인 기록).':'기록하지 않았어요.')}</dd><dt>${bi('Simulator test','시뮬레이터 확인')}</dt><dd>${bi(c.simulatorTest?'Own code tested (reported).':'Not recorded.',c.simulatorTest?'직접 만든 코드 확인 (본인 기록).':'기록하지 않았어요.')}</dd><dt>${bi('Physical micro:bit','실제 micro:bit')}</dt><dd>${B(phys[f.physical]||['Not reported.','기록하지 않았어요.'])}</dd><dt>${bi('Shared roles','역할 나누기')}</dt><dd>${bi(c.rolesSwapped?'Role change reported / both roles used.':'Not recorded.',c.rolesSwapped?'역할을 바꾸거나 두 역할을 했다고 기록했어요.':'기록하지 않았어요.')}</dd></dl></section><section><h2>${bi('My experiment','내 실험')}</h2><dl><dt>${bi('Change selected','고른 변화')}</dt><dd>${B(change[f.changeChoice]||['Not selected.','선택하지 않았어요.'])}</dd><dt>${bi('Prediction','예상')}</dt><dd>${response('prediction')}</dd><dt>${bi('What I changed and saw','바꾼 내용과 결과')}</dt><dd>${response('change')}</dd><dt>${bi('Retest location','다시 확인한 곳')}</dt><dd>${B(test[f.changeWhere]||['Not reported.','기록하지 않았어요.'])} ${bi(c.changeRetest?'Retest reported.':'Retest not reported.',c.changeRetest?'다시 확인했다고 기록했어요.':'다시 확인한 기록이 없어요.')}</dd></dl></section><section><h2>${bi('My explanation and next step','내 설명과 다음 단계')}</h2><dl><dt>${bi('A block I can explain','설명할 수 있는 블록')}</dt><dd>${response('final')}</dd><dt>${bi('Learning Pit Stop','배움 점검')}</dt><dd>${esc(f.phase||'Not selected')}</dd><dt>${bi('Next challenge','다음 도전')}</dt><dd>${esc(f.extension||'Not selected')}</dd><dt>${bi('Project saved','프로젝트 저장')}</dt><dd>${bi(c.projectSaved?'Saved / help requested (reported).':'Not reported.',c.projectSaved?'저장했거나 도움을 요청했다고 기록했어요.':'기록하지 않았어요.')}</dd><dt>${bi('Project location','프로젝트 위치')}</dt><dd>${esc(f.projectLocation||'—')}</dd></dl></section>${sequenceReport()}${radioReport()}<section><h2>${bi('Quick checks','짧은 확인 질문')}</h2><div class="table-wrap"><table><thead><tr><th>${bi('Question','질문')}</th><th>${bi('Recorded answer','기록한 답')}</th></tr></thead><tbody>${Object.entries(C.questions).map(([id,q])=>`<tr><td>${B(q.q)}</td><td>${s.answers[id]?B(q.options.find(([v])=>v===s.answers[id])?.[1]||['Not recorded','기록 없음']):bi('Not answered','아직 답하지 않았어요')}${s.answers[id]?bi(answered(id)?'✓ Correct':'Review needed',answered(id)?'✓ 정답':'다시 확인해요','p','caption'):''}</td></tr>`).join('')}</tbody></table></div></section><footer class="record-footer">${bi('Generated locally in this browser. Oral responses are self-reports, not audio recordings. This record does not contain the actual MakeCode project and has not been submitted to a teacher. Keep your code separately.','이 브라우저에서 만든 기록이에요. 말로 한 설명은 본인 기록이며 녹음이 아니에요. 이 기록에는 실제 MakeCode 프로젝트가 없고 선생님께 제출되지 않았어요. 코드는 따로 보관해요.')}</footer></article>`;
}
const recordCss=`*{box-sizing:border-box}body{font:15px/1.5 'Segoe UI',Arial,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;color:#183544;background:white;margin:0}.wrapper{max-width:900px;margin:auto;padding:30px}.en,.ko{display:block}.ko{font-size:.91em;color:#435c64;margin-top:3px}h1{font-size:30px;line-height:1.2}h1 .ko{font-size:18px}h2{font-size:20px;line-height:1.3;margin-top:26px}h2 .ko{font-size:14px}.eyebrow{font-size:11px;letter-spacing:.1em;color:#006e66}.caption,.record-footer{font-size:12px}.record-head{border-bottom:3px solid #006e66;padding-bottom:12px}dl{display:grid;grid-template-columns:180px 1fr;gap:10px 18px}dt{font-weight:bold}dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}p{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border-bottom:1px solid #d9e5df;text-align:left;vertical-align:top;padding:10px}th{background:#edf5ef}.record-footer{border-top:1px solid #d9e5df;margin-top:25px;padding-top:15px}button{font:inherit;background:#006e66;color:white;padding:10px 15px;border:0;border-radius:8px}.no-print{margin-bottom:20px}section{margin:20px 0}@media(max-width:600px){.wrapper{padding:18px}dl{grid-template-columns:1fr;gap:5px}dd{margin-bottom:10px}}@page{size:A4;margin:15mm}@media print{body{font-size:10pt}.wrapper{padding:0;max-width:none}.no-print{display:none}h1{font-size:22pt}h2{font-size:14pt}dl{grid-template-columns:155px 1fr;font-size:9.5pt}.ko{font-size:.88em}section,tr{break-inside:avoid}table{font-size:9pt}.caption,.record-footer{font-size:8pt}section{margin:14px 0}h2{margin-top:18px}dl{gap:8px 16px}td,th{padding:8px}.record-footer{break-inside:avoid;margin-top:14px;padding-top:10px}}`;
function recordDoc(){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week 3 Beacon + Radio Learning Record</title><style>${recordCss}</style></head><body><div class="wrapper"><button class="no-print" onclick="window.print()">Print / Save as PDF · 인쇄 / PDF로 저장</button>${report()}</div></body></html>`;}
function showRecord(){openDialog(['My learning record','내 배움 기록'],`<div class="actions no-print"><button class="primary" data-action="print">${bi('Print / Save as PDF','인쇄 / PDF로 저장')}</button><button class="secondary" data-action="download-record">${bi('Download HTML record','HTML 기록 내려받기')}</button></div><div class="note no-print">${bi('Save your MakeCode project separately. This record is for reviewing your learning; downloading is not submitting.','MakeCode 프로젝트는 따로 저장해요. 이 기록은 배움을 돌아보기 위한 것이며 내려받기는 제출이 아니에요.','p')}</div>${report()}`);}
function playPreview(){if(previewBusy)return;previewBusy=true;const seq=['diamond','blank','diamond','blank','tick'],times=[1100,500,1100,500,600];let i=0;const btn=$('[data-action="preview"]');if(btn)btn.disabled=true;const next=()=>{const el=$('#preview-leds');if(!el){previewBusy=false;return;}el.innerHTML=led(seq[i]);$('#preview-status').innerHTML=bi(i===4?'Ready. Make your own in MakeCode.':'Watch the order of the signal.',i===4?'준비됐어요. MakeCode에서 직접 만들어요.':'신호의 순서를 살펴봐요.');if(i<4){const wait=times[i];i++;previewTimer=setTimeout(next,wait);}else{previewBusy=false;if(btn)btn.disabled=false;}};next();}
document.addEventListener('submit',e=>{if(e.target.id!=='entry-form')return;e.preventDefault();const name=$('#name').value.trim(),klass=$('#klass').value.trim();if(!name||(!klass&&name.toLowerCase()!=='teacher')){const er=$('#entry-error');er.hidden=false;er.innerHTML=bi('Please enter your name and class.','이름과 반을 입력해요.');return;}start({name,klass,device:$('#device').value,board:$('#board').value});});
document.addEventListener('click',e=>{
 const btn=e.target.closest('button,a');if(!btn)return;
 if(btn.dataset.go!==undefined&&s&&s.profile.teacher){go(Number(btn.dataset.go));return;}
 if(btn.dataset.answer&&s){s.answers[btn.dataset.answer]=btn.dataset.value;save();render();return;}
 if(btn.dataset.choice&&s){setField(btn.dataset.choice,btn.dataset.value);render();return;}
 if(btn.dataset.moveSignal!==undefined&&s){moveSignal(Number(btn.dataset.moveSignal),Number(btn.dataset.direction));return;}
 const action=btn.dataset.action;if(!action)return;
 if(action==='open-editor'){if(s)setField('openedEditor',true);return;}
 if(action==='resume'){try{const p=JSON.parse(localStorage.getItem('beetlebit-w3-linear-last')||localStorage.getItem('beetlebit-w3-radio-last')||'null');if(p)start(p,true);}catch{toast('Please enter your name again.','이름을 다시 입력해요.');}return;}
 if(action==='close'){$('#dialog').close();return;}
 if(!s)return;
 switch(action){
 case 'next':go(s.index+1);break;
 case 'prev':go(s.index-1);break;
 case 'tools':tools();break;
 case 'words':words();break;
 case 'record':showRecord();break;
 case 'guide':teacherGuide();break;
 case 'early-extension':if(s.profile.teacher){$('#dialog').close();go(C.cards.findIndex(c=>c.id==='extension'));}break;
 case 'transfer-help':openDialog(['Transfer help · stay on this step','전송 도움말 · 현재 단계 유지'],`<p>${bi('You are still on your radio task. Close this panel to carry on.','무선 활동을 계속하고 있어요. 이 도움말을 닫으면 이어서 할 수 있어요.')}</p>${transferInstructions()}`);break;
 case 'project':projectDownload(btn.dataset.kind);break;
 case 'run-map':runMap();break;
 case 'run-long':runLong();break;
 case 'run-signal':runSignal();break;
 case 'reset-map':cancelTimers();render();break;
 case 'preview':playPreview();break;
 case 'print':$('#print-root').innerHTML=report();window.print();break;
 case 'download-record':download('Week3-Beacon-'+s.profile.name.replace(/[^a-z0-9\uac00-\ud7a3_-]/gi,'_')+'-record.html',recordDoc(),'text/html;charset=utf-8');break;
 case 'signout':save();cancelTimers();$('#dialog').close();s=null;landing();window.scrollTo(0,0);break;
 }
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.id==='landing-lang'){lang=el.value;document.body.classList.toggle('bilingual',lang==='ko');return;}
 if(!s)return;
 if(el.id==='lesson-lang'){s.lang=el.value;lang=s.lang;document.body.classList.toggle('bilingual',s.lang==='ko');save();syncFooter();return;}
 if(el.id==='jump'&&s.profile.teacher){go(Number(el.value));return;}
 if(el.dataset.check){s.checks[el.dataset.check]=el.checked;save();updateProgress();return;}
 if(el.dataset.profile){s.profile[el.dataset.profile]=el.value;save();render();return;}
 if(el.matches('[data-radio-group]')){const n=Number(el.value);if(el.value===''||!Number.isInteger(n)||n<0||n>255){el.setAttribute('aria-invalid','true');toast('Choose a whole-number group from 0 to 255.','0부터 255까지의 정수를 골라요.');return;}el.removeAttribute('aria-invalid');if(n!==teamGroup()){for(const k of ['radio1Tried','radio1Repeat','radio2Tried','radio2Both','radioFixed'])s.checks[k]=false;delete s.fields.radio1Where;delete s.fields.radio2Where;}setField('radioGroup',n);render();return;}
 if(el.dataset.longCommand!==undefined){cancelTimers();s.mapLong.seq[Number(el.dataset.longCommand)]=el.value;s.mapLong.result=null;save();render();return;}
 if(el.dataset.command!==undefined){cancelTimers();s.map.seq[Number(el.dataset.command)]=el.value;s.map.result=null;save();render();return;}
 if(el.dataset.field){setField(el.dataset.field,el.value);}
});
document.addEventListener('input',e=>{if(s&&e.target.dataset.field)setField(e.target.dataset.field,e.target.value);});
window.addEventListener('pagehide',()=>{save();cancelTimers();});
window.addEventListener('afterprint',()=>{$('#print-root').innerHTML='';});
landing();
})();
